-- Add assigned_driver_id column to parcels table
ALTER TABLE parcels ADD COLUMN IF NOT EXISTS assigned_driver_id TEXT;

-- Add columns for tracking acceptance/refusal
ALTER TABLE parcels ADD COLUMN IF NOT EXISTS accepted_at TIMESTAMP WITH TIME ZONE;
ALTER TABLE parcels ADD COLUMN IF NOT EXISTS refused_at TIMESTAMP WITH TIME ZONE;
ALTER TABLE parcels ADD COLUMN IF NOT EXISTS refused_reason TEXT;

-- Create index for faster queries by assigned driver
CREATE INDEX IF NOT EXISTS idx_parcels_assigned_driver ON parcels(assigned_driver_id);

-- Update status check constraint to include 'accepted' and 'refused'
ALTER TABLE parcels DROP CONSTRAINT IF EXISTS parcels_status_check;
ALTER TABLE parcels ADD CONSTRAINT parcels_status_check 
  CHECK (status IN ('pending', 'assigned', 'accepted', 'refused', 'en_route_pickup', 'picked_up', 'en_route_delivery', 'delivered', 'cancelled'));

-- 1. Create drivers table
CREATE TABLE IF NOT EXISTS drivers (
  id TEXT PRIMARY KEY,
  name TEXT NOT NULL,
  phone TEXT NOT NULL,
  status TEXT NOT NULL DEFAULT 'available' CHECK (status IN ('available', 'busy', 'offline')),
  last_lat DOUBLE PRECISION,
  last_lng DOUBLE PRECISION,
  rating DOUBLE PRECISION DEFAULT 5.0,
  completed_deliveries INTEGER DEFAULT 0,
  vehicle_type TEXT DEFAULT 'moto' CHECK (vehicle_type IN ('moto', 'car', 'bicycle')),
  created_at TIMESTAMP WITH TIME ZONE DEFAULT NOW()
);

-- 2. Enable RLS on drivers table
ALTER TABLE drivers ENABLE ROW LEVEL SECURITY;

-- 3. Create RLS policies for drivers table
CREATE POLICY "Anyone can view drivers" ON drivers FOR SELECT USING (true);
CREATE POLICY "Drivers can update their own data" ON drivers FOR UPDATE USING (true);

-- 4. Update parcels status constraint to include new statuses
ALTER TABLE parcels DROP CONSTRAINT IF EXISTS parcels_status_check;
ALTER TABLE parcels ADD CONSTRAINT parcels_status_check 
  CHECK (status IN (
    'pending', 
    'assigned', 
    'accepted', 
    'refused', 
    'en_route_pickup', 
    'picked_up', 
    'en_route_delivery', 
    'delivering',
    'delivered', 
    'cancelled'
  ));

-- 5. Create index on assigned_driver_id for faster lookups
CREATE INDEX IF NOT EXISTS idx_parcels_assigned_driver_id ON parcels(assigned_driver_id);

-- 6. Create index on status for faster filtering
CREATE INDEX IF NOT EXISTS idx_parcels_status ON parcels(status);

-- 7. Create index on drivers status and location for nearby driver searches
CREATE INDEX IF NOT EXISTS idx_drivers_status ON drivers(status);
CREATE INDEX IF NOT EXISTS idx_drivers_location ON drivers(last_lat, last_lng);

-- Add sender_id column to parcels table
-- For now, we'll use sender_phone as the identifier since there's no auth system yet
ALTER TABLE parcels ADD COLUMN IF NOT EXISTS sender_id text;

-- Create an index for faster queries
CREATE INDEX IF NOT EXISTS idx_parcels_sender_id ON parcels(sender_id);

-- Update existing records to use sender_phone as sender_id
UPDATE parcels SET sender_id = sender_phone WHERE sender_id IS NULL;

-- Add avatar_url column if it doesn't exist
DO $$ 
BEGIN
  IF NOT EXISTS (SELECT 1 FROM information_schema.columns WHERE table_name = 'user_profiles' AND column_name = 'avatar_url') THEN
    ALTER TABLE user_profiles ADD COLUMN avatar_url text;
  END IF;
END $$;

-- Update the roles column default to include all required roles with correct defaults
ALTER TABLE user_profiles 
  ALTER COLUMN roles SET DEFAULT '{"driver": true, "passenger": true, "sender": false, "delivery": false}'::jsonb;

-- Update existing rows to ensure driver and passenger are always true
UPDATE user_profiles 
SET roles = jsonb_set(
  jsonb_set(
    COALESCE(roles, '{}'::jsonb),
    '{driver}',
    'true'::jsonb
  ),
  '{passenger}',
  'true'::jsonb
)
WHERE 
  (roles->>'driver')::boolean IS DISTINCT FROM true 
  OR (roles->>'passenger')::boolean IS DISTINCT FROM true
  OR roles IS NULL;

-- Create a function to enforce driver and passenger roles are always true
CREATE OR REPLACE FUNCTION enforce_carpooling_roles()
RETURNS TRIGGER AS $$
BEGIN
  -- Ensure driver and passenger are always true
  NEW.roles = jsonb_set(
    jsonb_set(
      COALESCE(NEW.roles, '{}'::jsonb),
      '{driver}',
      'true'::jsonb
    ),
    '{passenger}',
    'true'::jsonb
  );

  RETURN NEW;
END;
$$ LANGUAGE plpgsql;

-- Drop trigger if it exists
DROP TRIGGER IF EXISTS enforce_carpooling_roles_trigger ON user_profiles;

-- Create trigger to enforce carpooling roles on insert and update
CREATE TRIGGER enforce_carpooling_roles_trigger
  BEFORE INSERT OR UPDATE ON user_profiles
  FOR EACH ROW
  EXECUTE FUNCTION enforce_carpooling_roles();

-- Add comment to document the behavior
COMMENT ON COLUMN user_profiles.roles IS 'User roles: driver and passenger are always true (enforced by trigger), sender and delivery can be toggled';

