import { serve } from 'https://deno.land/std@0.168.0/http/server.ts';
import { createClient } from 'https://esm.sh/@supabase/supabase-js@2.39.0';

const TWILIO_ACCOUNT_SID = Deno.env.get('TWILIO_ACCOUNT_SID');
const TWILIO_AUTH_TOKEN = Deno.env.get('TWILIO_AUTH_TOKEN');
const TWILIO_WHATSAPP_NUMBER = Deno.env.get('TWILIO_WHATSAPP_NUMBER') || 'whatsapp:+14155238886';
const TWILIO_SMS_NUMBER = Deno.env.get('TWILIO_SMS_NUMBER');
const SUPABASE_URL = Deno.env.get('SUPABASE_URL')!;
const SUPABASE_SERVICE_ROLE_KEY = Deno.env.get('SUPABASE_SERVICE_ROLE_KEY')!;

interface OTPRequest {
  phoneNumber: string;
  method?: 'whatsapp' | 'sms';
  userId?: string;
}

interface VerifyOTPRequest {
  phoneNumber: string;
  otpCode: string;
  userId?: string;
}

const corsHeaders = {
  'Access-Control-Allow-Origin': '*',
  'Access-Control-Allow-Headers': 'authorization, x-client-info, apikey, content-type',
};

// Generate a 6-digit OTP code
function generateOTP(): string {
  return Math.floor(100000 + Math.random() * 900000).toString();
}

// Send OTP via Twilio
async function sendTwilioMessage(
  to: string,
  message: string,
  method: 'whatsapp' | 'sms'
): Promise<{ success: boolean; error?: string; sid?: string }> {
  try {
    if (!TWILIO_ACCOUNT_SID || !TWILIO_AUTH_TOKEN) {
      throw new Error('Twilio credentials not configured');
    }

    const fromNumber = method === 'whatsapp' ? TWILIO_WHATSAPP_NUMBER : TWILIO_SMS_NUMBER;
    const toNumber = method === 'whatsapp' ? `whatsapp:${to}` : to;

    if (!fromNumber) {
      throw new Error(`Twilio ${method} number not configured`);
    }

    const url = `https://api.twilio.com/2010-04-01/Accounts/${TWILIO_ACCOUNT_SID}/Messages.json`;
    const auth = btoa(`${TWILIO_ACCOUNT_SID}:${TWILIO_AUTH_TOKEN}`);

    const body = new URLSearchParams({
      To: toNumber,
      From: fromNumber,
      Body: message,
    });

    const response = await fetch(url, {
      method: 'POST',
      headers: {
        'Authorization': `Basic ${auth}`,
        'Content-Type': 'application/x-www-form-urlencoded',
      },
      body: body.toString(),
    });

    const data = await response.json();

    if (!response.ok) {
      console.error('Twilio error:', data);
      return {
        success: false,
        error: data.message || 'Failed to send message',
      };
    }

    console.log('Twilio message sent:', data.sid);
    return {
      success: true,
      sid: data.sid,
    };
  } catch (error) {
    console.error('Error sending Twilio message:', error);
    return {
      success: false,
      error: error.message,
    };
  }
}

serve(async (req) => {
  // Handle CORS preflight requests
  if (req.method === 'OPTIONS') {
    return new Response('ok', { headers: corsHeaders });
  }

  try {
    const supabase = createClient(SUPABASE_URL, SUPABASE_SERVICE_ROLE_KEY);
    const url = new URL(req.url);
    const action = url.pathname.split('/').pop();

    // Send OTP
    if (action === 'send' && req.method === 'POST') {
      const { phoneNumber, method = 'whatsapp', userId }: OTPRequest = await req.json();

      if (!phoneNumber) {
        return new Response(
          JSON.stringify({ success: false, error: 'Phone number is required' }),
          { status: 400, headers: { ...corsHeaders, 'Content-Type': 'application/json' } }
        );
      }

      // Normalize phone number (ensure it starts with +)
      const normalizedPhone = phoneNumber.startsWith('+') ? phoneNumber : `+${phoneNumber}`;

      // Generate OTP
      const otpCode = generateOTP();
      const expiresAt = new Date(Date.now() + 10 * 60 * 1000); // 10 minutes

      // Store OTP in database
      const { error: dbError } = await supabase
        .from('phone_verifications')
        .insert({
          phone_number: normalizedPhone,
          otp_code: otpCode,
          verification_method: method,
          expires_at: expiresAt.toISOString(),
          user_id: userId || null,
        });

      if (dbError) {
        console.error('Database error:', dbError);
        return new Response(
          JSON.stringify({ success: false, error: 'Failed to store OTP' }),
          { status: 500, headers: { ...corsHeaders, 'Content-Type': 'application/json' } }
        );
      }

      // Send OTP via Twilio
      const message = `Votre code de vérification Yombal Yoon est: ${otpCode}. Ce code expire dans 10 minutes.`;
      const twilioResult = await sendTwilioMessage(normalizedPhone, message, method);

      if (!twilioResult.success) {
        // If WhatsApp fails, try SMS as fallback
        if (method === 'whatsapp' && TWILIO_SMS_NUMBER) {
          console.log('WhatsApp failed, trying SMS fallback...');
          const smsResult = await sendTwilioMessage(normalizedPhone, message, 'sms');

          if (smsResult.success) {
            // Update verification method in database
            await supabase
              .from('phone_verifications')
              .update({ verification_method: 'sms' })
              .eq('phone_number', normalizedPhone)
              .eq('otp_code', otpCode);

            return new Response(
              JSON.stringify({
                success: true,
                message: 'Code OTP envoyé par SMS (WhatsApp indisponible)',
                method: 'sms',
              }),
              { status: 200, headers: { ...corsHeaders, 'Content-Type': 'application/json' } }
            );
          }
        }

        return new Response(
          JSON.stringify({
            success: false,
            error: twilioResult.error || 'Failed to send OTP',
          }),
          { status: 500, headers: { ...corsHeaders, 'Content-Type': 'application/json' } }
        );
      }

      const methodLabel = method === 'whatsapp' ? 'WhatsApp' : 'SMS';
      return new Response(
        JSON.stringify({
          success: true,
          message: `Code OTP envoyé par ${methodLabel}`,
          method,
        }),
        { status: 200, headers: { ...corsHeaders, 'Content-Type': 'application/json' } }
      );
    }

    // Verify OTP
    if (action === 'verify' && req.method === 'POST') {
      const { phoneNumber, otpCode, userId }: VerifyOTPRequest = await req.json();

      if (!phoneNumber || !otpCode) {
        return new Response(
          JSON.stringify({ success: false, error: 'Phone number and OTP code are required' }),
          { status: 400, headers: { ...corsHeaders, 'Content-Type': 'application/json' } }
        );
      }

      // Normalize phone number
      const normalizedPhone = phoneNumber.startsWith('+') ? phoneNumber : `+${phoneNumber}`;

      // Find the most recent non-expired verification
      const { data: verification, error: fetchError } = await supabase
        .from('phone_verifications')
        .select('*')
        .eq('phone_number', normalizedPhone)
        .eq('otp_code', otpCode)
        .eq('is_verified', false)
        .gt('expires_at', new Date().toISOString())
        .order('created_at', { ascending: false })
        .limit(1)
        .single();

      if (fetchError || !verification) {
        // Increment attempts for all matching verifications
        await supabase
          .from('phone_verifications')
          .update({ attempts: supabase.rpc('increment', { x: 1 }) })
          .eq('phone_number', normalizedPhone)
          .eq('is_verified', false);

        return new Response(
          JSON.stringify({
            success: false,
            error: 'Code OTP invalide ou expiré',
          }),
          { status: 400, headers: { ...corsHeaders, 'Content-Type': 'application/json' } }
        );
      }

      // Check attempts limit
      if (verification.attempts >= 5) {
        return new Response(
          JSON.stringify({
            success: false,
            error: 'Trop de tentatives. Veuillez demander un nouveau code.',
          }),
          { status: 400, headers: { ...corsHeaders, 'Content-Type': 'application/json' } }
        );
      }

      // Mark as verified
      const { error: updateError } = await supabase
        .from('phone_verifications')
        .update({
          is_verified: true,
          verified_at: new Date().toISOString(),
        })
        .eq('id', verification.id);

      if (updateError) {
        console.error('Error updating verification:', updateError);
        return new Response(
          JSON.stringify({ success: false, error: 'Failed to verify OTP' }),
          { status: 500, headers: { ...corsHeaders, 'Content-Type': 'application/json' } }
        );
      }

      // Update user profile if userId is provided
      if (userId) {
        await supabase
          .from('user_profiles')
          .update({
            phone_number: normalizedPhone,
            is_phone_verified: true,
            phone_verified_at: new Date().toISOString(),
          })
          .eq('id', userId);
      }

      return new Response(
        JSON.stringify({
          success: true,
          message: 'Numéro vérifié avec succès !',
        }),
        { status: 200, headers: { ...corsHeaders, 'Content-Type': 'application/json' } }
      );
    }

    return new Response(
      JSON.stringify({ error: 'Invalid endpoint' }),
      { status: 404, headers: { ...corsHeaders, 'Content-Type': 'application/json' } }
    );
  } catch (error) {
    console.error('Error:', error);
    return new Response(
      JSON.stringify({ success: false, error: error.message }),
      { status: 500, headers: { ...corsHeaders, 'Content-Type': 'application/json' } }
    );
  }
});

