-- Create a function to send notifications when a booking is created
CREATE OR REPLACE FUNCTION notify_driver_new_booking()
RETURNS TRIGGER AS $$
DECLARE
  ride_data RECORD;
BEGIN
  -- Get ride details
  SELECT * INTO ride_data
  FROM carpool_rides
  WHERE id = NEW.ride_id;

  -- Log the notification (in production, this would call an Edge Function)
  RAISE NOTICE 'New booking notification: Driver % should be notified about booking % from passenger %',
    ride_data.driver_name, NEW.id, NEW.passenger_name;

  RETURN NEW;
END;
$$ LANGUAGE plpgsql;

-- Create a function to send notifications when a booking status changes
CREATE OR REPLACE FUNCTION notify_passenger_booking_status()
RETURNS TRIGGER AS $$
DECLARE
  ride_data RECORD;
BEGIN
  -- Only notify if status changed to accepted or refused
  IF NEW.status != OLD.status AND (NEW.status = 'accepted' OR NEW.status = 'refused') THEN
    -- Get ride details
    SELECT * INTO ride_data
    FROM carpool_rides
    WHERE id = NEW.ride_id;

    -- Log the notification (in production, this would call an Edge Function)
    RAISE NOTICE 'Booking status notification: Passenger % should be notified that booking % was %',
      NEW.passenger_name, NEW.id, NEW.status;
  END IF;

  RETURN NEW;
END;
$$ LANGUAGE plpgsql;

-- Drop existing triggers if they exist
DROP TRIGGER IF EXISTS trigger_notify_driver_new_booking ON carpool_bookings;
DROP TRIGGER IF EXISTS trigger_notify_passenger_booking_status ON carpool_bookings;

-- Create trigger for new bookings (notify driver)
CREATE TRIGGER trigger_notify_driver_new_booking
  AFTER INSERT ON carpool_bookings
  FOR EACH ROW
  EXECUTE FUNCTION notify_driver_new_booking();

-- Create trigger for booking status changes (notify passenger)
CREATE TRIGGER trigger_notify_passenger_booking_status
  AFTER UPDATE ON carpool_bookings
  FOR EACH ROW
  EXECUTE FUNCTION notify_passenger_booking_status();

-- Add comment
COMMENT ON FUNCTION notify_driver_new_booking() IS 'Sends notification to driver when a new booking is created';
COMMENT ON FUNCTION notify_passenger_booking_status() IS 'Sends notification to passenger when booking status changes';

