// Supabase Edge Function: match-ride-alerts
// Matches newly published rides with passenger alerts and sends notifications

import { serve } from 'https://deno.land/std@0.168.0/http/server.ts';
import { createClient } from 'https://esm.sh/@supabase/supabase-js@2';

// Production mode flag - set via environment variable
const isProduction = Deno.env.get("IS_PRODUCTION_MODE") === "true";

const corsHeaders = {
  'Access-Control-Allow-Origin': '*',
  'Access-Control-Allow-Headers': 'authorization, x-client-info, apikey, content-type',
};

interface RideData {
  id: string;
  driver_name: string;
  driver_phone: string;
  departure_city: string;
  arrival_city: string;
  departure_datetime: string;
  seats_available: number;
  price_per_seat: number;
  vehicle_type?: string;
}

interface RideAlert {
  id: string;
  user_id: string;
  user_name: string;
  user_phone: string;
  origin_city: string;
  destination_city: string;
  date_from?: string;
  date_to?: string;
  time_range_start?: string;
  time_range_end?: string;
  max_price?: number;
  min_seats: number;
  accepts_luggage: boolean;
  is_active: boolean;
}

serve(async (req) => {
  // Handle CORS preflight requests
  if (req.method === 'OPTIONS') {
    return new Response('ok', { headers: corsHeaders });
  }

  try {
    const supabaseUrl = Deno.env.get('SUPABASE_URL')!;
    const supabaseKey = Deno.env.get('SUPABASE_SERVICE_ROLE_KEY')!;
    const supabase = createClient(supabaseUrl, supabaseKey);

    const rideData: RideData = await req.json();

    console.log('📥 Processing ride for alert matching:', {
      rideId: rideData.id,
      from: rideData.departure_city,
      to: rideData.arrival_city,
      mode: isProduction ? 'Production' : 'Test',
    });

    // Fetch all active alerts
    const { data: alerts, error: alertsError } = await supabase
      .from('ride_alerts')
      .select('*')
      .eq('is_active', true);

    if (alertsError) {
      console.error('❌ Error fetching alerts:', alertsError);
      throw alertsError;
    }

    if (!alerts || alerts.length === 0) {
      console.log('ℹ️ No active alerts found');
      return new Response(
        JSON.stringify({
          success: true,
          message: 'No active alerts to match',
          matchedAlerts: 0,
          mode: isProduction ? 'production' : 'test',
        }),
        {
          headers: { ...corsHeaders, 'Content-Type': 'application/json' },
          status: 200,
        }
      );
    }

    console.log(`🔍 Found ${alerts.length} active alerts, checking for matches...`);

    // Match alerts with the ride
    const matchedAlerts: RideAlert[] = [];
    const rideDatetime = new Date(rideData.departure_datetime);
    const rideDate = rideDatetime.toISOString().split('T')[0];
    const rideTime = rideDatetime.toTimeString().split(' ')[0].substring(0, 5); // HH:MM

    for (const alert of alerts as RideAlert[]) {
      let matches = true;

      // Check origin city (case-insensitive, partial match)
      if (!rideData.departure_city.toLowerCase().includes(alert.origin_city.toLowerCase()) &&
          !alert.origin_city.toLowerCase().includes(rideData.departure_city.toLowerCase())) {
        matches = false;
      }

      // Check destination city (case-insensitive, partial match)
      if (!rideData.arrival_city.toLowerCase().includes(alert.destination_city.toLowerCase()) &&
          !alert.destination_city.toLowerCase().includes(rideData.arrival_city.toLowerCase())) {
        matches = false;
      }

      // Check date range
      if (alert.date_from && rideDate < alert.date_from) {
        matches = false;
      }
      if (alert.date_to && rideDate > alert.date_to) {
        matches = false;
      }

      // Check time range
      if (alert.time_range_start && rideTime < alert.time_range_start) {
        matches = false;
      }
      if (alert.time_range_end && rideTime > alert.time_range_end) {
        matches = false;
      }

      // Check max price
      if (alert.max_price && rideData.price_per_seat > alert.max_price) {
        matches = false;
      }

      // Check minimum seats
      if (rideData.seats_available < alert.min_seats) {
        matches = false;
      }

      if (matches) {
        matchedAlerts.push(alert);
        console.log(`✅ Alert matched for user ${alert.user_name} (${alert.user_phone})`);
      }
    }

    console.log(`🎯 Found ${matchedAlerts.length} matching alerts`);

    // Send notifications to matched passengers
    const notificationPromises = matchedAlerts.map(async (alert) => {
      try {
        // Format date and time for notification
        const formattedDate = new Date(rideData.departure_datetime).toLocaleDateString('fr-FR');
        const formattedTime = new Date(rideData.departure_datetime).toLocaleTimeString('fr-FR', {
          hour: '2-digit',
          minute: '2-digit',
        });

        // Create in-app notification
        const notificationData = {
          user_id: alert.user_id,
          type: 'ride_alert_match',
          title: '🚗 Nouveau trajet disponible !',
          body: `${rideData.departure_city} → ${rideData.arrival_city} le ${formattedDate} à ${formattedTime}. ${rideData.price_per_seat} FCFA/place. Réserve ta place !`,
          data: {
            rideId: rideData.id,
            alertId: alert.id,
            driverName: rideData.driver_name,
            departureCity: rideData.departure_city,
            arrivalCity: rideData.arrival_city,
            departureDate: formattedDate,
            departureTime: formattedTime,
            pricePerSeat: rideData.price_per_seat,
            seatsAvailable: rideData.seats_available,
            vehicleType: rideData.vehicle_type,
          },
          read: false,
          created_at: new Date().toISOString(),
        };

        // Store notification in database (you may need to create a notifications table)
        // For now, we'll just log it
        console.log('📤 Notification prepared for:', alert.user_name, notificationData);

        // In production, you would send push notification here
        // using Expo Push Notifications or similar service
        if (isProduction) {
          // TODO: Integrate with Expo Push Notification service
          console.log('📱 Would send push notification in production mode');
        }

        return {
          success: true,
          userId: alert.user_id,
          userName: alert.user_name,
        };
      } catch (error) {
        console.error(`❌ Error sending notification to ${alert.user_name}:`, error);
        return {
          success: false,
          userId: alert.user_id,
          userName: alert.user_name,
          error: error.message,
        };
      }
    });

    const notificationResults = await Promise.all(notificationPromises);
    const successCount = notificationResults.filter(r => r.success).length;

    console.log(`✅ Sent ${successCount}/${matchedAlerts.length} notifications successfully`);

    return new Response(
      JSON.stringify({
        success: true,
        message: `Matched ${matchedAlerts.length} alerts and sent ${successCount} notifications`,
        matchedAlerts: matchedAlerts.length,
        notificationsSent: successCount,
        results: notificationResults,
        mode: isProduction ? 'production' : 'test',
      }),
      {
        headers: { ...corsHeaders, 'Content-Type': 'application/json' },
        status: 200,
      }
    );
  } catch (error) {
    console.error('❌ Error in match-ride-alerts:', error);
    return new Response(
      JSON.stringify({
        success: false,
        error: error.message,
        mode: isProduction ? 'production' : 'test',
      }),
      {
        headers: { ...corsHeaders, 'Content-Type': 'application/json' },
        status: 500,
      }
    );
  }
});

// Supabase Edge Function: send-covoiturage-notifications-part2
// Handles notifications for DURING and AFTER the ride (Part 2)
// - Ride start
// - Last-minute cancellations (driver)
// - Passenger cancellations
// - Ride end
// - Rating requests

import { serve } from 'https://deno.land/std@0.168.0/http/server.ts';
import { createClient } from 'https://esm.sh/@supabase/supabase-js@2';

// Production mode flag - set via environment variable
const isProduction = Deno.env.get("IS_PRODUCTION_MODE") === "true";

// Twilio credentials for WhatsApp
const TWILIO_ACCOUNT_SID = Deno.env.get("TWILIO_ACCOUNT_SID");
const TWILIO_AUTH_TOKEN = Deno.env.get("TWILIO_AUTH_TOKEN");
const TWILIO_WHATSAPP_FROM = Deno.env.get("TWILIO_WHATSAPP_FROM") || "whatsapp:+14155238886";

const corsHeaders = {
  'Access-Control-Allow-Origin': '*',
  'Access-Control-Allow-Headers': 'authorization, x-client-info, apikey, content-type',
};

interface NotificationRequest {
  type: 
    | 'ride_started'
    | 'ride_cancelled_last_minute'
    | 'passenger_cancelled'
    | 'ride_ended'
    | 'rating_request';
  rideId: string;
  driverName?: string;
  driverPhone?: string;
  passengerName?: string;
  passengerPhone?: string;
  passengerId?: string;
  numberOfPassengers?: number;
  route?: {
    from: string;
    to: string;
    date: string;
    time: string;
  };
  tripSummary?: {
    duration: string;
    price: number;
  };
}

/**
 * Send WhatsApp notification via Twilio
 */
async function sendWhatsAppNotification(
  to: string,
  message: string
): Promise<{ success: boolean; error?: string }> {
  if (!TWILIO_ACCOUNT_SID || !TWILIO_AUTH_TOKEN) {
    console.log('⚠️ Twilio credentials not configured, skipping WhatsApp');
    return { success: false, error: 'Twilio not configured' };
  }

  try {
    // Ensure phone number is in E.164 format
    let formattedPhone = to;
    if (!to.startsWith('+')) {
      formattedPhone = '+' + to;
    }
    if (!to.startsWith('+221') && !to.startsWith('221')) {
      formattedPhone = '+221' + to.replace(/^0+/, '');
    }

    const whatsappTo = `whatsapp:${formattedPhone}`;

    console.log('📱 Sending WhatsApp to:', whatsappTo);

    const response = await fetch(
      `https://api.twilio.com/2010-04-01/Accounts/${TWILIO_ACCOUNT_SID}/Messages.json`,
      {
        method: 'POST',
        headers: {
          'Authorization': 'Basic ' + btoa(`${TWILIO_ACCOUNT_SID}:${TWILIO_AUTH_TOKEN}`),
          'Content-Type': 'application/x-www-form-urlencoded',
        },
        body: new URLSearchParams({
          From: TWILIO_WHATSAPP_FROM,
          To: whatsappTo,
          Body: message,
        }),
      }
    );

    const data = await response.json();

    if (!response.ok) {
      console.error('❌ Twilio error:', data);
      return { success: false, error: data.message || 'Twilio API error' };
    }

    console.log('✅ WhatsApp sent successfully:', data.sid);
    return { success: true };
  } catch (error) {
    console.error('❌ Error sending WhatsApp:', error);
    return { success: false, error: error.message };
  }
}

/**
 * Log notification to database
 */
async function logNotification(
  supabase: any,
  type: string,
  recipient: string,
  channel: 'push' | 'whatsapp' | 'in-app',
  status: 'sent' | 'failed',
  message: string,
  metadata?: any
): Promise<void> {
  try {
    const { error } = await supabase
      .from('notification_logs')
      .insert({
        type,
        recipient,
        channel,
        status,
        message,
        metadata: metadata || {},
        created_at: new Date().toISOString(),
      });

    if (error) {
      console.error('❌ Error logging notification:', error);
    } else {
      console.log('✅ Notification logged');
    }
  } catch (error) {
    console.error('❌ Exception logging notification:', error);
  }
}

serve(async (req) => {
  // Handle CORS preflight requests
  if (req.method === 'OPTIONS') {
    return new Response('ok', { headers: corsHeaders });
  }

  try {
    const data: NotificationRequest = await req.json();

    console.log('📥 Processing covoiturage notification (Part 2):', {
      type: data.type,
      rideId: data.rideId,
      mode: isProduction ? 'Production' : 'Test',
    });

    // Initialize Supabase client
    const supabaseUrl = Deno.env.get('SUPABASE_URL') || '';
    const supabaseKey = Deno.env.get('SUPABASE_SERVICE_ROLE_KEY') || '';
    const supabase = createClient(supabaseUrl, supabaseKey);

    let notificationTitle = '';
    let notificationBody = '';
    let whatsappMessage = '';
    let recipientPhone = '';
    let shouldSendWhatsApp = false;

    switch (data.type) {
      case 'ride_started':
        // 3.1. Démarrage du trajet
        // Passengers: In-app status update (handled by client)
        notificationTitle = '🚗 Trajet démarré';
        notificationBody = `Le trajet ${data.route?.from} → ${data.route?.to} a démarré`;
        recipientPhone = data.passengerPhone || '';
        shouldSendWhatsApp = false; // Only in-app
        break;

      case 'ride_cancelled_last_minute':
        // 3.2. Annulation de dernière minute (conducteur)
        notificationTitle = 'Trajet annulé ❌';
        notificationBody = `${data.driverName} a annulé ${data.route?.from} → ${data.route?.to}`;
        whatsappMessage = `Le conducteur a annulé votre trajet ${data.route?.from} → ${data.route?.to} du ${data.route?.date}. Vous pouvez en réserver un autre sur Yombal Yoon.`;
        recipientPhone = data.passengerPhone || '';
        shouldSendWhatsApp = true; // Push + WhatsApp + In-app
        break;

      case 'passenger_cancelled':
        // 3.3. Annulation par le passager
        notificationTitle = '❌ Annulation de réservation';
        notificationBody = `${data.passengerName} a annulé sa réservation`;
        recipientPhone = data.driverPhone || '';
        shouldSendWhatsApp = false; // Push + In-app only
        break;

      case 'ride_ended':
        // 4.1. Arrivée / Fin du trajet
        notificationTitle = '✅ Trajet terminé';
        notificationBody = `Le trajet ${data.route?.from} → ${data.route?.to} est terminé`;
        recipientPhone = data.passengerPhone || data.driverPhone || '';
        shouldSendWhatsApp = false; // In-app summary only
        break;

      case 'rating_request':
        // 4.2. Demande de notation (10-30 minutes après la fin)
        if (data.driverPhone) {
          // Request to driver
          notificationTitle = '⭐ Note tes passagers';
          notificationBody = `Comment s'est passé ton trajet ? Note tes passagers`;
          recipientPhone = data.driverPhone;
        } else if (data.passengerPhone) {
          // Request to passenger
          notificationTitle = '⭐ Note ton conducteur';
          notificationBody = `Note ton conducteur pour le trajet ${data.route?.from} → ${data.route?.to} 🚗`;
          recipientPhone = data.passengerPhone;
        }
        shouldSendWhatsApp = false; // Push + In-app only
        break;
    }

    console.log('📤 Notification prepared:', {
      title: notificationTitle,
      body: notificationBody,
      recipient: recipientPhone,
      shouldSendWhatsApp,
    });

    // Send WhatsApp if needed
    let whatsappResult = null;
    if (shouldSendWhatsApp && whatsappMessage && recipientPhone) {
      whatsappResult = await sendWhatsAppNotification(recipientPhone, whatsappMessage);

      // Log WhatsApp notification
      await logNotification(
        supabase,
        data.type,
        recipientPhone,
        'whatsapp',
        whatsappResult.success ? 'sent' : 'failed',
        whatsappMessage,
        { rideId: data.rideId, error: whatsappResult.error }
      );
    }

    // Log push notification (actual push is handled by client)
    await logNotification(
      supabase,
      data.type,
      recipientPhone,
      'push',
      'sent',
      notificationBody,
      { rideId: data.rideId }
    );

    // Log in-app notification
    await logNotification(
      supabase,
      data.type,
      recipientPhone,
      'in-app',
      'sent',
      notificationBody,
      { rideId: data.rideId }
    );

    return new Response(
      JSON.stringify({
        success: true,
        message: 'Notifications sent successfully',
        notification: {
          title: notificationTitle,
          body: notificationBody,
          recipient: recipientPhone,
        },
        whatsapp: whatsappResult,
        mode: isProduction ? 'production' : 'test',
      }),
      {
        headers: { ...corsHeaders, 'Content-Type': 'application/json' },
        status: 200,
      }
    );
  } catch (error) {
    console.error('❌ Error in send-covoiturage-notifications-part2:', error);
    return new Response(
      JSON.stringify({
        success: false,
        error: error.message,
        mode: isProduction ? 'production' : 'test',
      }),
      {
        headers: { ...corsHeaders, 'Content-Type': 'application/json' },
        status: 500,
      }
    );
  }
});

