ADD COLUMN IF NOT EXISTS whatsapp_optin BOOLEAN DEFAULT true;

COMMENT ON COLUMN user_profiles.whatsapp_optin IS 'Opt-in pour recevoir des notifications WhatsApp';

-- 2. Mise à jour de la table rides (carpool_rides) pour ajouter les champs manquants
ALTER TABLE carpool_rides 
ADD COLUMN IF NOT EXISTS driver_id TEXT REFERENCES user_profiles(id),
ADD COLUMN IF NOT EXISTS origin TEXT,
ADD COLUMN IF NOT EXISTS destination TEXT,
ADD COLUMN IF NOT EXISTS date_departure DATE,
ADD COLUMN IF NOT EXISTS time_departure TIME,
ADD COLUMN IF NOT EXISTS price INTEGER,
ADD COLUMN IF NOT EXISTS meeting_point TEXT;

-- Copier les données existantes vers les nouveaux champs
UPDATE carpool_rides 
SET 
  origin = departure_city,
  destination = arrival_city,
  date_departure = DATE(departure_datetime),
  time_departure = departure_datetime::TIME,
  price = price_per_seat
WHERE origin IS NULL;

-- Ajouter un commentaire sur la table
COMMENT ON TABLE carpool_rides IS 'Table des trajets de covoiturage avec informations complètes';

-- 3. Mise à jour de la table ride_reservations (carpool_bookings) pour ajouter les champs manquants
ALTER TABLE carpool_bookings 
ADD COLUMN IF NOT EXISTS passenger_id TEXT REFERENCES user_profiles(id),
ADD COLUMN IF NOT EXISTS updated_at TIMESTAMP WITH TIME ZONE DEFAULT now();

-- Ajouter des contraintes de statut plus complètes
ALTER TABLE carpool_bookings 
DROP CONSTRAINT IF EXISTS carpool_bookings_status_check;

ALTER TABLE carpool_bookings 
ADD CONSTRAINT carpool_bookings_status_check 
CHECK (status IN ('pending', 'accepted', 'refused', 'cancelled_by_driver', 'cancelled_by_passenger'));

COMMENT ON TABLE carpool_bookings IS 'Table des réservations de covoiturage avec statuts étendus';

-- 4. Mise à jour de la table ride_alerts pour correspondre au modèle
ALTER TABLE ride_alerts 
ADD COLUMN IF NOT EXISTS origin TEXT,
ADD COLUMN IF NOT EXISTS destination TEXT,
ADD COLUMN IF NOT EXISTS date_filter DATE,
ADD COLUMN IF NOT EXISTS active BOOLEAN DEFAULT true;

-- Copier les données existantes
UPDATE ride_alerts 
SET 
  origin = origin_city,
  destination = destination_city,
  date_filter = date_from,
  active = is_active
WHERE origin IS NULL;

COMMENT ON TABLE ride_alerts IS 'Alertes de trajets pour passagers - notifications automatiques lors de publication de trajets correspondants';

-- 5. Créer la table device_tokens pour les tokens push
CREATE TABLE IF NOT EXISTS device_tokens (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  user_id TEXT NOT NULL REFERENCES user_profiles(id) ON DELETE CASCADE,
  expo_push_token TEXT,
  fcm_token TEXT,
  platform TEXT NOT NULL CHECK (platform IN ('ios', 'android', 'web')),
  active BOOLEAN DEFAULT true,
  last_used_at TIMESTAMP WITH TIME ZONE DEFAULT now(),
  created_at TIMESTAMP WITH TIME ZONE DEFAULT now(),
  updated_at TIMESTAMP WITH TIME ZONE DEFAULT now(),
  UNIQUE(user_id, platform)
);

CREATE INDEX IF NOT EXISTS idx_device_tokens_user_id ON device_tokens(user_id);
CREATE INDEX IF NOT EXISTS idx_device_tokens_active ON device_tokens(active) WHERE active = true;

COMMENT ON TABLE device_tokens IS 'Tokens de notification push (Expo/FCM) pour chaque utilisateur et plateforme';

-- 6. Créer la table notifications pour les notifications in-app
CREATE TABLE IF NOT EXISTS notifications (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  user_id TEXT NOT NULL REFERENCES user_profiles(id) ON DELETE CASCADE,
  type TEXT NOT NULL CHECK (type IN (
    'ride_created', 
    'ride_published',
    'reservation_requested', 
    'reservation_accepted', 
    'reservation_refused',
    'reservation_cancelled_by_driver',
    'reservation_cancelled_by_passenger',
    'ride_cancelled',
    'ride_started',
    'ride_ended',
    'driver_arrived',
    'reminder_j_minus_1',
    'reminder_h_minus_1',
    'rating_request',
    'alert_match'
  )),
  title TEXT NOT NULL,
  message TEXT NOT NULL,
  metadata JSONB DEFAULT '{}'::jsonb,
  is_read BOOLEAN DEFAULT false,
  created_at TIMESTAMP WITH TIME ZONE DEFAULT now(),
  read_at TIMESTAMP WITH TIME ZONE
);

CREATE INDEX IF NOT EXISTS idx_notifications_user_id ON notifications(user_id);
CREATE INDEX IF NOT EXISTS idx_notifications_created_at ON notifications(created_at DESC);
CREATE INDEX IF NOT EXISTS idx_notifications_is_read ON notifications(is_read) WHERE is_read = false;
CREATE INDEX IF NOT EXISTS idx_notifications_type ON notifications(type);

COMMENT ON TABLE notifications IS 'Notifications in-app affichées dans la cloche de l''application';

-- 7. Mise à jour de la table notification_logs pour correspondre au modèle
ALTER TABLE notification_logs 
ADD COLUMN IF NOT EXISTS user_id TEXT REFERENCES user_profiles(id),
ADD COLUMN IF NOT EXISTS payload JSONB DEFAULT '{}'::jsonb,
ADD COLUMN IF NOT EXISTS error_message TEXT;

-- Renommer la colonne message en payload si nécessaire
DO $$ 
BEGIN
  IF EXISTS (SELECT 1 FROM information_schema.columns WHERE table_name = 'notification_logs' AND column_name = 'message') THEN
    ALTER TABLE notification_logs RENAME COLUMN message TO payload_text;
  END IF;
END $$;

-- Mettre à jour les contraintes
ALTER TABLE notification_logs 
DROP CONSTRAINT IF EXISTS notification_logs_channel_check;

ALTER TABLE notification_logs 
ADD CONSTRAINT notification_logs_channel_check 
CHECK (channel IN ('in_app', 'push', 'whatsapp', 'sms'));

ALTER TABLE notification_logs 
DROP CONSTRAINT IF EXISTS notification_logs_status_check;

ALTER TABLE notification_logs 
ADD CONSTRAINT notification_logs_status_check 
CHECK (status IN ('success', 'error', 'pending'));

CREATE INDEX IF NOT EXISTS idx_notification_logs_user_id ON notification_logs(user_id);
CREATE INDEX IF NOT EXISTS idx_notification_logs_created_at ON notification_logs(created_at DESC);
CREATE INDEX IF NOT EXISTS idx_notification_logs_status ON notification_logs(status);
CREATE INDEX IF NOT EXISTS idx_notification_logs_channel ON notification_logs(channel);

COMMENT ON TABLE notification_logs IS 'Logs de toutes les notifications envoyées (in-app, push, WhatsApp, SMS) avec statut et erreurs';

-- ================================================
-- RLS POLICIES
-- ================================================

-- Enable RLS on all tables
ALTER TABLE device_tokens ENABLE ROW LEVEL SECURITY;
ALTER TABLE notifications ENABLE ROW LEVEL SECURITY;

-- Device tokens policies
CREATE POLICY "Users can view their own device tokens"
  ON device_tokens FOR SELECT
  USING (user_id = current_setting('app.current_user_id', true));

CREATE POLICY "Users can insert their own device tokens"
  ON device_tokens FOR INSERT
  WITH CHECK (user_id = current_setting('app.current_user_id', true));

CREATE POLICY "Users can update their own device tokens"
  ON device_tokens FOR UPDATE
  USING (user_id = current_setting('app.current_user_id', true));

CREATE POLICY "Users can delete their own device tokens"
  ON device_tokens FOR DELETE
  USING (user_id = current_setting('app.current_user_id', true));

-- Notifications policies
CREATE POLICY "Users can view their own notifications"
  ON notifications FOR SELECT
  USING (user_id = current_setting('app.current_user_id', true));

CREATE POLICY "Users can update their own notifications"
  ON notifications FOR UPDATE
  USING (user_id = current_setting('app.current_user_id', true));

-- Notification logs policies (read-only for users, write for system)
CREATE POLICY "Users can view their own notification logs"
  ON notification_logs FOR SELECT
  USING (user_id = current_setting('app.current_user_id', true));

-- ================================================
-- TRIGGERS
-- ================================================

-- Trigger to update updated_at on device_tokens
CREATE OR REPLACE FUNCTION update_device_tokens_updated_at()
RETURNS TRIGGER AS $$
BEGIN
  NEW.updated_at = now();
  RETURN NEW;
END;
$$ LANGUAGE plpgsql;

CREATE TRIGGER device_tokens_updated_at
  BEFORE UPDATE ON device_tokens
  FOR EACH ROW
  EXECUTE FUNCTION update_device_tokens_updated_at();

-- Trigger to update read_at on notifications
CREATE OR REPLACE FUNCTION update_notifications_read_at()
RETURNS TRIGGER AS $$
BEGIN
  IF NEW.is_read = true AND OLD.is_read = false THEN
    NEW.read_at = now();
  END IF;
  RETURN NEW;
END;
$$ LANGUAGE plpgsql;

CREATE TRIGGER notifications_read_at
  BEFORE UPDATE ON notifications
  FOR EACH ROW
  EXECUTE FUNCTION update_notifications_read_at();

-- ================================================
-- INDEXES FOR PERFORMANCE
-- ================================================

-- Additional indexes for ride matching with alerts
CREATE INDEX IF NOT EXISTS idx_carpool_rides_departure_datetime ON carpool_rides(departure_datetime);
CREATE INDEX IF NOT EXISTS idx_carpool_rides_origin_destination ON carpool_rides(origin, destination);
CREATE INDEX IF NOT EXISTS idx_carpool_rides_status ON carpool_rides(ride_status);

CREATE INDEX IF NOT EXISTS idx_ride_alerts_active ON ride_alerts(is_active) WHERE is_active = true;
CREATE INDEX IF NOT EXISTS idx_ride_alerts_origin_destination ON ride_alerts(origin, destination);
CREATE INDEX IF NOT EXISTS idx_ride_alerts_date_range ON ride_alerts(date_from, date_to);

-- ================================================
-- HELPER FUNCTIONS
-- ================================================

-- Function to get active device tokens for a user
CREATE OR REPLACE FUNCTION get_user_device_tokens(p_user_id TEXT)
RETURNS TABLE (
  token TEXT,
  platform TEXT,
  token_type TEXT
) AS $$
BEGIN
  RETURN QUERY
  SELECT 
    COALESCE(expo_push_token, fcm_token) as token,
    device_tokens.platform,
    CASE 
      WHEN expo_push_token IS NOT NULL THEN 'expo'
      WHEN fcm_token IS NOT NULL THEN 'fcm'
      ELSE 'unknown'
    END as token_type
  FROM device_tokens
  WHERE user_id = p_user_id 
    AND active = true
    AND (expo_push_token IS NOT NULL OR fcm_token IS NOT NULL);
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;

-- Function to create a notification
CREATE OR REPLACE FUNCTION create_notification(
  p_user_id TEXT,
  p_type TEXT,
  p_title TEXT,
  p_message TEXT,
  p_metadata JSONB DEFAULT '{}'::jsonb
)
RETURNS UUID AS $$
DECLARE
  v_notification_id UUID;
BEGIN
  INSERT INTO notifications (user_id, type, title, message, metadata)
  VALUES (p_user_id, p_type, p_title, p_message, p_metadata)
  RETURNING id INTO v_notification_id;

  RETURN v_notification_id;
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;

-- Function to log a notification
CREATE OR REPLACE FUNCTION log_notification(
  p_user_id TEXT,
  p_channel TEXT,
  p_payload JSONB,
  p_status TEXT,
  p_error_message TEXT DEFAULT NULL
)
RETURNS UUID AS $$
DECLARE
  v_log_id UUID;
BEGIN
  INSERT INTO notification_logs (user_id, channel, payload, status, error_message)
  VALUES (p_user_id, p_channel, p_payload, p_status, p_error_message)
  RETURNING id INTO v_log_id;

  RETURN v_log_id;
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;

