import "jsr:@supabase/functions-js/edge-runtime.d.ts";
import { createClient } from 'npm:@supabase/supabase-js@2.83.0';

// Initialize Supabase client
const supabaseUrl = Deno.env.get('SUPABASE_URL')!;
const supabaseServiceKey = Deno.env.get('SUPABASE_SERVICE_ROLE_KEY')!;
const supabase = createClient(supabaseUrl, supabaseServiceKey);

// Twilio credentials
const TWILIO_ACCOUNT_SID = Deno.env.get('TWILIO_ACCOUNT_SID');
const TWILIO_AUTH_TOKEN = Deno.env.get('TWILIO_AUTH_TOKEN');
const TWILIO_WHATSAPP_NUMBER = Deno.env.get('TWILIO_WHATSAPP_NUMBER');
const IS_PRODUCTION_MODE = Deno.env.get('IS_PRODUCTION_MODE') === 'true';

interface NotificationRequest {
  type: string;
  userId: string;
  title: string;
  message: string;
  metadata?: any;
  channels?: ('in_app' | 'push' | 'whatsapp')[];
  phoneNumber?: string;
}

interface NotificationResponse {
  success: boolean;
  notificationId?: string;
  channels: {
    in_app?: { success: boolean; id?: string; error?: string };
    push?: { success: boolean; error?: string };
    whatsapp?: { success: boolean; error?: string };
  };
}

/**
 * Send WhatsApp notification via Twilio
 */
async function sendWhatsAppNotification(
  phoneNumber: string,
  message: string
): Promise<{ success: boolean; error?: string }> {
  if (!TWILIO_ACCOUNT_SID || !TWILIO_AUTH_TOKEN || !TWILIO_WHATSAPP_NUMBER) {
    console.log('⚠️ Twilio credentials not configured, skipping WhatsApp');
    return { success: false, error: 'Twilio not configured' };
  }

  try {
    // Format phone number for Twilio (must start with +)
    const formattedPhone = phoneNumber.startsWith('+') ? phoneNumber : `+${phoneNumber}`;

    const twilioUrl = `https://api.twilio.com/2010-04-01/Accounts/${TWILIO_ACCOUNT_SID}/Messages.json`;
    const auth = btoa(`${TWILIO_ACCOUNT_SID}:${TWILIO_AUTH_TOKEN}`);

    const response = await fetch(twilioUrl, {
      method: 'POST',
      headers: {
        'Authorization': `Basic ${auth}`,
        'Content-Type': 'application/x-www-form-urlencoded',
      },
      body: new URLSearchParams({
        From: `whatsapp:${TWILIO_WHATSAPP_NUMBER}`,
        To: `whatsapp:${formattedPhone}`,
        Body: message,
      }),
    });

    if (!response.ok) {
      const error = await response.text();
      console.error('❌ Twilio WhatsApp error:', error);
      return { success: false, error };
    }

    console.log('✅ WhatsApp notification sent successfully');
    return { success: true };
  } catch (error) {
    console.error('❌ Error sending WhatsApp notification:', error);
    return { success: false, error: String(error) };
  }
}

/**
 * Send push notification via Expo
 */
async function sendPushNotification(
  userId: string,
  title: string,
  message: string,
  data?: any
): Promise<{ success: boolean; error?: string }> {
  try {
    // Get user's device tokens
    const { data: tokens, error: tokensError } = await supabase
      .from('device_tokens')
      .select('expo_push_token, fcm_token, platform')
      .eq('user_id', userId)
      .eq('active', true);

    if (tokensError || !tokens || tokens.length === 0) {
      console.log('⚠️ No active device tokens found for user:', userId);
      return { success: false, error: 'No device tokens' };
    }

    // Send to Expo Push Notification service
    const messages = tokens
      .filter(t => t.expo_push_token)
      .map(token => ({
        to: token.expo_push_token,
        sound: 'default',
        title,
        body: message,
        data: data || {},
        priority: 'high',
        channelId: 'covoiturage-general',
      }));

    if (messages.length === 0) {
      console.log('⚠️ No Expo push tokens available');
      return { success: false, error: 'No Expo tokens' };
    }

    const response = await fetch('https://exp.host/--/api/v2/push/send', {
      method: 'POST',
      headers: {
        'Accept': 'application/json',
        'Content-Type': 'application/json',
      },
      body: JSON.stringify(messages),
    });

    if (!response.ok) {
      const error = await response.text();
      console.error('❌ Expo push error:', error);
      return { success: false, error };
    }

    console.log('✅ Push notification sent successfully');
    return { success: true };
  } catch (error) {
    console.error('❌ Error sending push notification:', error);
    return { success: false, error: String(error) };
  }
}

/**
 * Create in-app notification
 */
async function createInAppNotification(
  userId: string,
  type: string,
  title: string,
  message: string,
  metadata?: any
): Promise<{ success: boolean; id?: string; error?: string }> {
  try {
    const { data, error } = await supabase
      .from('notifications')
      .insert({
        user_id: userId,
        type,
        title,
        message,
        metadata: metadata || {},
        is_read: false,
      })
      .select('id')
      .single();

    if (error) {
      console.error('❌ Error creating in-app notification:', error);
      return { success: false, error: error.message };
    }

    console.log('✅ In-app notification created:', data.id);
    return { success: true, id: data.id };
  } catch (error) {
    console.error('❌ Error creating in-app notification:', error);
    return { success: false, error: String(error) };
  }
}

/**
 * Log notification attempt
 */
async function logNotification(
  userId: string,
  channel: string,
  payload: any,
  status: 'success' | 'error',
  errorMessage?: string
): Promise<void> {
  try {
    await supabase.from('notification_logs').insert({
      user_id: userId,
      channel,
      payload,
      status,
      error_message: errorMessage,
    });
  } catch (error) {
    console.error('❌ Error logging notification:', error);
  }
}

/**
 * Main handler
 */
Deno.serve(async (req: Request) => {
  // Handle CORS
  if (req.method === 'OPTIONS') {
    return new Response(null, {
      headers: {
        'Access-Control-Allow-Origin': '*',
        'Access-Control-Allow-Methods': 'POST, OPTIONS',
        'Access-Control-Allow-Headers': 'Content-Type, Authorization',
      },
    });
  }

  try {
    const request: NotificationRequest = await req.json();
    console.log('📨 Notification request:', request);

    const {
      type,
      userId,
      title,
      message,
      metadata,
      channels = ['in_app', 'push'],
      phoneNumber,
    } = request;

    // Validate required fields
    if (!type || !userId || !title || !message) {
      return new Response(
        JSON.stringify({ error: 'Missing required fields' }),
        { status: 400, headers: { 'Content-Type': 'application/json' } }
      );
    }

    const response: NotificationResponse = {
      success: false,
      channels: {},
    };

    // 1. Create in-app notification
    if (channels.includes('in_app')) {
      const inAppResult = await createInAppNotification(
        userId,
        type,
        title,
        message,
        metadata
      );
      response.channels.in_app = inAppResult;
      if (inAppResult.success) {
        response.notificationId = inAppResult.id;
      }
      await logNotification(
        userId,
        'in_app',
        { type, title, message, metadata },
        inAppResult.success ? 'success' : 'error',
        inAppResult.error
      );
    }

    // 2. Send push notification
    if (channels.includes('push')) {
      const pushResult = await sendPushNotification(
        userId,
        title,
        message,
        metadata
      );
      response.channels.push = pushResult;
      await logNotification(
        userId,
        'push',
        { type, title, message, metadata },
        pushResult.success ? 'success' : 'error',
        pushResult.error
      );
    }

    // 3. Send WhatsApp notification (if phone number provided and opted in)
    if (channels.includes('whatsapp') && phoneNumber) {
      // Check if user has opted in for WhatsApp
      const { data: user } = await supabase
        .from('user_profiles')
        .select('whatsapp_optin')
        .eq('id', userId)
        .single();

      if (user?.whatsapp_optin) {
        const whatsappResult = await sendWhatsAppNotification(
          phoneNumber,
          `${title}\n\n${message}`
        );
        response.channels.whatsapp = whatsappResult;
        await logNotification(
          userId,
          'whatsapp',
          { type, title, message, phoneNumber },
          whatsappResult.success ? 'success' : 'error',
          whatsappResult.error
        );
      } else {
        console.log('⚠️ User has not opted in for WhatsApp notifications');
        response.channels.whatsapp = {
          success: false,
          error: 'User not opted in',
        };
      }
    }

    // Determine overall success
    response.success = Object.values(response.channels).some(c => c.success);

    return new Response(JSON.stringify(response), {
      status: 200,
      headers: {
        'Content-Type': 'application/json',
        'Access-Control-Allow-Origin': '*',
      },
    });
  } catch (error) {
    console.error('❌ Error processing notification request:', error);
    return new Response(
      JSON.stringify({ error: String(error) }),
      {
        status: 500,
        headers: {
          'Content-Type': 'application/json',
          'Access-Control-Allow-Origin': '*',
        },
      }
    );
  }
});

// Supabase Edge Function: send-notification-unified
// Unified notification handler for all Covoiturage events
// Handles: in-app, push (Expo/FCM), and WhatsApp (Twilio) notifications

import { serve } from 'https://deno.land/std@0.168.0/http/server.ts';
import { createClient } from 'https://esm.sh/@supabase/supabase-js@2';

// ================================================
// CONFIGURATION
// ================================================

const IS_PRODUCTION_MODE = Deno.env.get("IS_PRODUCTION_MODE") === "true";
const TWILIO_ACCOUNT_SID = Deno.env.get("TWILIO_ACCOUNT_SID");
const TWILIO_AUTH_TOKEN = Deno.env.get("TWILIO_AUTH_TOKEN");
const TWILIO_WHATSAPP_FROM = Deno.env.get("TWILIO_WHATSAPP_FROM") || "whatsapp:+14155238886";

const corsHeaders = {
  'Access-Control-Allow-Origin': '*',
  'Access-Control-Allow-Headers': 'authorization, x-client-info, apikey, content-type',
};

// ================================================
// TYPES
// ================================================

interface NotificationPayload {
  type: string;
  userId: string;
  title: string;
  message: string;
  metadata?: any;
  channels?: ('in_app' | 'push' | 'whatsapp')[];
  phoneNumber?: string;
}

interface NotificationResponse {
  success: boolean;
  notificationId?: string;
  channels: {
    in_app?: { success: boolean; id?: string; error?: string };
    push?: { success: boolean; error?: string };
    whatsapp?: { success: boolean; error?: string };
  };
}

// ================================================
// HELPER FUNCTIONS
// ================================================

/**
 * Create in-app notification
 */
async function createInAppNotification(
  supabase: any,
  userId: string,
  type: string,
  title: string,
  message: string,
  metadata: any
): Promise<{ success: boolean; id?: string; error?: string }> {
  try {
    const { data, error } = await supabase
      .from('notifications')
      .insert({
        user_id: userId,
        type,
        title,
        message,
        metadata: metadata || {},
        is_read: false,
        created_at: new Date().toISOString(),
      })
      .select('id')
      .single();

    if (error) {
      console.error('❌ Error creating in-app notification:', error);
      return { success: false, error: error.message };
    }

    console.log('✅ In-app notification created:', data.id);
    return { success: true, id: data.id };
  } catch (error) {
    console.error('❌ Exception creating in-app notification:', error);
    return { success: false, error: error.message };
  }
}

/**
 * Send push notification via Expo
 */
async function sendPushNotification(
  supabase: any,
  userId: string,
  title: string,
  message: string,
  metadata: any
): Promise<{ success: boolean; error?: string }> {
  try {
    // Get active device tokens for user
    const { data: tokens, error: tokenError } = await supabase
      .from('device_tokens')
      .select('*')
      .eq('user_id', userId)
      .eq('active', true);

    if (tokenError) {
      console.error('❌ Error fetching device tokens:', tokenError);
      return { success: false, error: tokenError.message };
    }

    if (!tokens || tokens.length === 0) {
      console.log('⚠️ No active device tokens found for user:', userId);
      return { success: false, error: 'No active device tokens' };
    }

    // Send push notification to each token
    const pushPromises = tokens.map(async (token: any) => {
      try {
        const pushToken = token.expo_push_token || token.fcm_token;
        if (!pushToken) {
          console.log('⚠️ No push token found for device:', token.id);
          return { success: false, tokenId: token.id };
        }

        // Send via Expo Push API
        const response = await fetch('https://exp.host/--/api/v2/push/send', {
          method: 'POST',
          headers: {
            'Content-Type': 'application/json',
            'Accept': 'application/json',
          },
          body: JSON.stringify({
            to: pushToken,
            title,
            body: message,
            data: metadata || {},
            sound: 'default',
            priority: 'high',
          }),
        });

        const result = await response.json();

        if (result.data && result.data[0] && result.data[0].status === 'error') {
          console.error('❌ Push notification error:', result.data[0].message);

          // Deactivate invalid tokens
          if (result.data[0].details && result.data[0].details.error === 'DeviceNotRegistered') {
            await supabase
              .from('device_tokens')
              .update({ active: false })
              .eq('id', token.id);
            console.log('🔄 Deactivated invalid token:', token.id);
          }

          return { success: false, tokenId: token.id, error: result.data[0].message };
        }

        console.log('✅ Push notification sent to token:', token.id);

        // Update last_used_at
        await supabase
          .from('device_tokens')
          .update({ last_used_at: new Date().toISOString() })
          .eq('id', token.id);

        return { success: true, tokenId: token.id };
      } catch (error) {
        console.error('❌ Error sending push to token:', token.id, error);
        return { success: false, tokenId: token.id, error: error.message };
      }
    });

    const results = await Promise.all(pushPromises);
    const successCount = results.filter(r => r.success).length;

    console.log(`📤 Push notifications sent: ${successCount}/${tokens.length}`);

    return {
      success: successCount > 0,
      error: successCount === 0 ? 'All push notifications failed' : undefined,
    };
  } catch (error) {
    console.error('❌ Exception sending push notifications:', error);
    return { success: false, error: error.message };
  }
}

/**
 * Send WhatsApp notification via Twilio
 */
async function sendWhatsAppNotification(
  phoneNumber: string,
  message: string
): Promise<{ success: boolean; error?: string }> {
  if (!TWILIO_ACCOUNT_SID || !TWILIO_AUTH_TOKEN) {
    console.log('⚠️ Twilio credentials not configured, skipping WhatsApp');
    return { success: false, error: 'Twilio not configured' };
  }

  try {
    // Format phone number to E.164
    let formattedPhone = phoneNumber;
    if (!phoneNumber.startsWith('+')) {
      if (phoneNumber.startsWith('221')) {
        formattedPhone = '+' + phoneNumber;
      } else {
        formattedPhone = '+221' + phoneNumber.replace(/^0+/, '');
      }
    }

    const whatsappTo = `whatsapp:${formattedPhone}`;

    console.log('📱 Sending WhatsApp to:', whatsappTo);

    const response = await fetch(
      `https://api.twilio.com/2010-04-01/Accounts/${TWILIO_ACCOUNT_SID}/Messages.json`,
      {
        method: 'POST',
        headers: {
          'Authorization': 'Basic ' + btoa(`${TWILIO_ACCOUNT_SID}:${TWILIO_AUTH_TOKEN}`),
          'Content-Type': 'application/x-www-form-urlencoded',
        },
        body: new URLSearchParams({
          From: TWILIO_WHATSAPP_FROM,
          To: whatsappTo,
          Body: message,
        }),
      }
    );

    const data = await response.json();

    if (!response.ok) {
      console.error('❌ Twilio error:', data);
      return { success: false, error: data.message || 'Twilio API error' };
    }

    console.log('✅ WhatsApp sent successfully:', data.sid);
    return { success: true };
  } catch (error) {
    console.error('❌ Error sending WhatsApp:', error);
    return { success: false, error: error.message };
  }
}

/**
 * Log notification to database
 */
async function logNotification(
  supabase: any,
  userId: string,
  channel: 'in_app' | 'push' | 'whatsapp',
  status: 'success' | 'error',
  payload: any,
  errorMessage?: string
): Promise<void> {
  try {
    const { error } = await supabase
      .from('notification_logs')
      .insert({
        user_id: userId,
        channel,
        status,
        payload,
        error_message: errorMessage,
        created_at: new Date().toISOString(),
      });

    if (error) {
      console.error('❌ Error logging notification:', error);
    }
  } catch (error) {
    console.error('❌ Exception logging notification:', error);
  }
}

/**
 * Check if user has WhatsApp opt-in
 */
async function checkWhatsAppOptIn(
  supabase: any,
  userId: string
): Promise<boolean> {
  try {
    const { data, error } = await supabase
      .from('user_profiles')
      .select('whatsapp_optin')
      .eq('id', userId)
      .single();

    if (error || !data) {
      console.log('⚠️ Could not check WhatsApp opt-in for user:', userId);
      return false;
    }

    return data.whatsapp_optin === true;
  } catch (error) {
    console.error('❌ Exception checking WhatsApp opt-in:', error);
    return false;
  }
}

