serve(async (req) => {
  // Handle CORS preflight
  if (req.method === 'OPTIONS') {
    return new Response('ok', { headers: corsHeaders });
  }

  try {
    const payload: NotificationPayload = await req.json();

    console.log('📥 Processing notification:', {
      type: payload.type,
      userId: payload.userId,
      channels: payload.channels,
      mode: IS_PRODUCTION_MODE ? 'Production' : 'Test',
    });

    // Initialize Supabase client
    const supabaseUrl = Deno.env.get('SUPABASE_URL') || '';
    const supabaseKey = Deno.env.get('SUPABASE_SERVICE_ROLE_KEY') || '';
    const supabase = createClient(supabaseUrl, supabaseKey);

    const response: NotificationResponse = {
      success: false,
      channels: {},
    };

    // Default channels if not specified
    const channels = payload.channels || ['in_app', 'push'];

    // Check WhatsApp opt-in if WhatsApp channel is requested
    let canSendWhatsApp = false;
    if (channels.includes('whatsapp')) {
      canSendWhatsApp = await checkWhatsAppOptIn(supabase, payload.userId);
      if (!canSendWhatsApp) {
        console.log('⚠️ User has not opted in to WhatsApp notifications');
      }
    }

    // Send in-app notification
    if (channels.includes('in_app')) {
      const inAppResult = await createInAppNotification(
        supabase,
        payload.userId,
        payload.type,
        payload.title,
        payload.message,
        payload.metadata
      );
      response.channels.in_app = inAppResult;

      await logNotification(
        supabase,
        payload.userId,
        'in_app',
        inAppResult.success ? 'success' : 'error',
        { type: payload.type, title: payload.title, message: payload.message },
        inAppResult.error
      );

      if (inAppResult.success) {
        response.notificationId = inAppResult.id;
      }
    }

    // Send push notification (only in production mode or if explicitly testing)
    if (channels.includes('push')) {
      if (IS_PRODUCTION_MODE) {
        const pushResult = await sendPushNotification(
          supabase,
          payload.userId,
          payload.title,
          payload.message,
          payload.metadata
        );
        response.channels.push = pushResult;

        await logNotification(
          supabase,
          payload.userId,
          'push',
          pushResult.success ? 'success' : 'error',
          { type: payload.type, title: payload.title, message: payload.message },
          pushResult.error
        );
      } else {
        console.log('⚠️ Push notification skipped (test mode)');
        response.channels.push = { success: false, error: 'Test mode - push skipped' };
      }
    }

    // Send WhatsApp notification (only if opted in and in production mode)
    if (channels.includes('whatsapp') && canSendWhatsApp && payload.phoneNumber) {
      if (IS_PRODUCTION_MODE) {
        const whatsappResult = await sendWhatsAppNotification(
          payload.phoneNumber,
          payload.message
        );
        response.channels.whatsapp = whatsappResult;

        await logNotification(
          supabase,
          payload.userId,
          'whatsapp',
          whatsappResult.success ? 'success' : 'error',
          { type: payload.type, message: payload.message, phoneNumber: payload.phoneNumber },
          whatsappResult.error
        );
      } else {
        console.log('⚠️ WhatsApp notification skipped (test mode)');
        response.channels.whatsapp = { success: false, error: 'Test mode - WhatsApp skipped' };
      }
    }

    // Determine overall success
    response.success = Object.values(response.channels).some(
      (channel: any) => channel && channel.success
    );

    console.log('✅ Notification processing complete:', response);

    return new Response(
      JSON.stringify({
        ...response,
        mode: IS_PRODUCTION_MODE ? 'production' : 'test',
      }),
      {
        headers: { ...corsHeaders, 'Content-Type': 'application/json' },
        status: 200,
      }
    );
  } catch (error) {
    console.error('❌ Error in send-notification-unified:', error);
    return new Response(
      JSON.stringify({
        success: false,
        error: error.message,
        mode: IS_PRODUCTION_MODE ? 'production' : 'test',
      }),
      {
        headers: { ...corsHeaders, 'Content-Type': 'application/json' },
        status: 500,
      }
    );
  }
});

// Edge Function: on-ride-created
// Triggered when a driver publishes a new ride
// Tasks:
// - Create in-app notification for driver
// - Match ride with ride_alerts
// - Notify matching passengers

import { serve } from 'https://deno.land/std@0.168.0/http/server.ts';
import { createClient } from 'https://esm.sh/@supabase/supabase-js@2';

const corsHeaders = {
  'Access-Control-Allow-Origin': '*',
  'Access-Control-Allow-Headers': 'authorization, x-client-info, apikey, content-type',
};

interface RideCreatedPayload {
  rideId: string;
  driverId: string;
  origin: string;
  destination: string;
  dateDeparture: string;
  timeDeparture: string;
  price: number;
  seatsAvailable: number;
}

serve(async (req) => {
  if (req.method === 'OPTIONS') {
    return new Response('ok', { headers: corsHeaders });
  }

  try {
    const payload: RideCreatedPayload = await req.json();

    console.log('📥 on-ride-created:', payload);

    const supabaseUrl = Deno.env.get('SUPABASE_URL') || '';
    const supabaseKey = Deno.env.get('SUPABASE_SERVICE_ROLE_KEY') || '';
    const supabase = createClient(supabaseUrl, supabaseKey);

    // 1. Notify driver that ride is published
    const { data: driver } = await supabase
      .from('user_profiles')
      .select('full_name, phone_number')
      .eq('id', payload.driverId)
      .single();

    if (driver) {
      await supabase.functions.invoke('send-notification-unified', {
        body: {
          type: 'ride_published',
          userId: payload.driverId,
          title: '✅ Trajet publié',
          message: `Ton trajet ${payload.origin} → ${payload.destination} du ${payload.dateDeparture} à ${payload.timeDeparture} est en ligne`,
          metadata: {
            rideId: payload.rideId,
            origin: payload.origin,
            destination: payload.destination,
            dateDeparture: payload.dateDeparture,
            timeDeparture: payload.timeDeparture,
          },
          channels: ['in_app', 'push'],
        },
      });
    }

    // 2. Match with ride alerts
    const { data: alerts } = await supabase
      .from('ride_alerts')
      .select('*')
      .eq('active', true)
      .or(`origin.eq.${payload.origin},origin_city.eq.${payload.origin}`)
      .or(`destination.eq.${payload.destination},destination_city.eq.${payload.destination}`);

    console.log(`🔍 Found ${alerts?.length || 0} matching alerts`);

    // 3. Notify matching passengers
    if (alerts && alerts.length > 0) {
      for (const alert of alerts) {
        // Check date filter
        if (alert.date_filter) {
          const alertDate = new Date(alert.date_filter);
          const rideDate = new Date(payload.dateDeparture);
          if (alertDate.toDateString() !== rideDate.toDateString()) {
            continue;
          }
        }

        // Check date range
        if (alert.date_from && alert.date_to) {
          const rideDate = new Date(payload.dateDeparture);
          const dateFrom = new Date(alert.date_from);
          const dateTo = new Date(alert.date_to);
          if (rideDate < dateFrom || rideDate > dateTo) {
            continue;
          }
        }

        // Check price
        if (alert.max_price && payload.price > alert.max_price) {
          continue;
        }

        // Check seats
        if (alert.min_seats && payload.seatsAvailable < alert.min_seats) {
          continue;
        }

        // Send notification to passenger
        await supabase.functions.invoke('send-notification-unified', {
          body: {
            type: 'alert_match',
            userId: alert.user_id,
            title: '🔔 Nouveau trajet disponible !',
            message: `Nouveau trajet : ${payload.origin} → ${payload.destination} le ${payload.dateDeparture} à ${payload.timeDeparture}. Réserve ta place.`,
            metadata: {
              rideId: payload.rideId,
              alertId: alert.id,
              origin: payload.origin,
              destination: payload.destination,
              dateDeparture: payload.dateDeparture,
              timeDeparture: payload.timeDeparture,
              price: payload.price,
              seatsAvailable: payload.seatsAvailable,
            },
            channels: ['in_app', 'push'],
            phoneNumber: alert.user_phone,
          },
        });

        console.log(`✅ Notified passenger ${alert.user_id} for alert ${alert.id}`);
      }
    }

    return new Response(
      JSON.stringify({
        success: true,
        alertsMatched: alerts?.length || 0,
      }),
      {
        headers: { ...corsHeaders, 'Content-Type': 'application/json' },
        status: 200,
      }
    );
  } catch (error) {
    console.error('❌ Error in on-ride-created:', error);
    return new Response(
      JSON.stringify({ success: false, error: error.message }),
      {
        headers: { ...corsHeaders, 'Content-Type': 'application/json' },
        status: 500,
      }
    );
  }
});

// Edge Function: on-reservation-requested
// Triggered when a passenger requests a reservation
// Tasks:
// - Create in-app notification for driver
// - Send push to driver
// - Send WhatsApp if departure < 2h and whatsapp_optin

import { serve } from 'https://deno.land/std@0.168.0/http/server.ts';
import { createClient } from 'https://esm.sh/@supabase/supabase-js@2';

const corsHeaders = {
  'Access-Control-Allow-Origin': '*',
  'Access-Control-Allow-Headers': 'authorization, x-client-info, apikey, content-type',
};

interface ReservationRequestedPayload {
  reservationId: string;
  rideId: string;
  passengerId: string;
  passengerName: string;
  passengerPhone: string;
  numberOfPassengers: number;
  driverId: string;
  driverPhone: string;
  origin: string;
  destination: string;
  dateDeparture: string;
  timeDeparture: string;
}

serve(async (req) => {
  if (req.method === 'OPTIONS') {
    return new Response('ok', { headers: corsHeaders });
  }

  try {
    const payload: ReservationRequestedPayload = await req.json();

    console.log('📥 on-reservation-requested:', payload);

    const supabaseUrl = Deno.env.get('SUPABASE_URL') || '';
    const supabaseKey = Deno.env.get('SUPABASE_SERVICE_ROLE_KEY') || '';
    const supabase = createClient(supabaseUrl, supabaseKey);

    // Check if departure is within 2 hours
    const departureDateTime = new Date(`${payload.dateDeparture}T${payload.timeDeparture}`);
    const now = new Date();
    const hoursUntilDeparture = (departureDateTime.getTime() - now.getTime()) / (1000 * 60 * 60);
    const isUrgent = hoursUntilDeparture < 2;

    console.log(`⏰ Hours until departure: ${hoursUntilDeparture.toFixed(2)}, urgent: ${isUrgent}`);

    // Determine channels
    const channels: ('in_app' | 'push' | 'whatsapp')[] = ['in_app', 'push'];
    if (isUrgent) {
      channels.push('whatsapp');
    }

    // Notify driver
    await supabase.functions.invoke('send-notification-unified', {
      body: {
        type: 'reservation_requested',
        userId: payload.driverId,
        title: '🚗 Nouvelle demande de réservation !',
        message: `${payload.passengerName} souhaite réserver ${payload.numberOfPassengers} place(s) pour ${payload.origin} → ${payload.destination} le ${payload.dateDeparture}`,
        metadata: {
          reservationId: payload.reservationId,
          rideId: payload.rideId,
          passengerId: payload.passengerId,
          passengerName: payload.passengerName,
          numberOfPassengers: payload.numberOfPassengers,
          origin: payload.origin,
          destination: payload.destination,
          dateDeparture: payload.dateDeparture,
          timeDeparture: payload.timeDeparture,
          isUrgent,
        },
        channels,
        phoneNumber: payload.driverPhone,
      },
    });

    // Create in-app notification for passenger (confirmation)
    await supabase.functions.invoke('send-notification-unified', {
      body: {
        type: 'reservation_sent',
        userId: payload.passengerId,
        title: '✅ Demande envoyée',
        message: 'Demande envoyée ! En attente de validation.',
        metadata: {
          reservationId: payload.reservationId,
          rideId: payload.rideId,
        },
        channels: ['in_app'],
      },
    });

    return new Response(
      JSON.stringify({
        success: true,
        isUrgent,
        channelsUsed: channels,
      }),
      {
        headers: { ...corsHeaders, 'Content-Type': 'application/json' },
        status: 200,
      }
    );
  } catch (error) {
    console.error('❌ Error in on-reservation-requested:', error);
    return new Response(
      JSON.stringify({ success: false, error: error.message }),
      {
        headers: { ...corsHeaders, 'Content-Type': 'application/json' },
        status: 500,
      }
    );
  }
});

