// Edge Function: on-ride-reminders
// Scheduled cron job for ride reminders
// Tasks:
// - J-1 reminder (24h before)
// - H-1 reminder (1h before)
// - Send push to driver + passengers
// - Send WhatsApp for H-1 reminders

import { serve } from 'https://deno.land/std@0.168.0/http/server.ts';
import { createClient } from 'https://esm.sh/@supabase/supabase-js@2';

const corsHeaders = {
  'Access-Control-Allow-Origin': '*',
  'Access-Control-Allow-Headers': 'authorization, x-client-info, apikey, content-type',
};

serve(async (req) => {
  if (req.method === 'OPTIONS') {
    return new Response('ok', { headers: corsHeaders });
  }

  try {
    console.log('📥 on-ride-reminders: Starting scheduled job');

    const supabaseUrl = Deno.env.get('SUPABASE_URL') || '';
    const supabaseKey = Deno.env.get('SUPABASE_SERVICE_ROLE_KEY') || '';
    const supabase = createClient(supabaseUrl, supabaseKey);

    const now = new Date();

    // Calculate time windows
    const in24Hours = new Date(now.getTime() + 24 * 60 * 60 * 1000);
    const in23Hours = new Date(now.getTime() + 23 * 60 * 60 * 1000);
    const in1Hour = new Date(now.getTime() + 60 * 60 * 1000);
    const in59Minutes = new Date(now.getTime() + 59 * 60 * 1000);

    let jMinus1Count = 0;
    let hMinus1Count = 0;

    // ================================================
    // J-1 REMINDERS (24h before)
    // ================================================

    const { data: ridesJMinus1 } = await supabase
      .from('carpool_rides')
      .select('*, user_profiles!carpool_rides_driver_id_fkey(full_name, phone_number)')
      .gte('departure_datetime', in23Hours.toISOString())
      .lte('departure_datetime', in24Hours.toISOString())
      .in('ride_status', ['pending', 'started'])
      .not('status', 'eq', 'cancelled');

    if (ridesJMinus1 && ridesJMinus1.length > 0) {
      console.log(`📅 Found ${ridesJMinus1.length} rides for J-1 reminders`);

      for (const ride of ridesJMinus1) {
        const driver = ride.user_profiles;

        // Notify driver
        await supabase.functions.invoke('send-notification-unified', {
          body: {
            type: 'reminder_j_minus_1',
            userId: ride.driver_id,
            title: '📅 Rappel : Trajet demain',
            message: `Tu conduis demain ${ride.departure_city || ride.origin} → ${ride.arrival_city || ride.destination} à ${ride.time_departure || new Date(ride.departure_datetime).toLocaleTimeString('fr-FR', { hour: '2-digit', minute: '2-digit' })}`,
            metadata: {
              rideId: ride.id,
              origin: ride.departure_city || ride.origin,
              destination: ride.arrival_city || ride.destination,
              dateDeparture: ride.date_departure || new Date(ride.departure_datetime).toISOString().split('T')[0],
              timeDeparture: ride.time_departure || new Date(ride.departure_datetime).toLocaleTimeString('fr-FR', { hour: '2-digit', minute: '2-digit' }),
            },
            channels: ['in_app', 'push'],
            phoneNumber: driver?.phone_number,
          },
        });

        // Get confirmed passengers
        const { data: bookings } = await supabase
          .from('carpool_bookings')
          .select('*, user_profiles!carpool_bookings_passenger_id_fkey(full_name, phone_number)')
          .eq('ride_id', ride.id)
          .eq('status', 'accepted');

        if (bookings && bookings.length > 0) {
          for (const booking of bookings) {
            const passenger = booking.user_profiles;

            await supabase.functions.invoke('send-notification-unified', {
              body: {
                type: 'reminder_j_minus_1',
                userId: booking.passenger_id,
                title: '📅 Rappel : Trajet demain',
                message: `Rappel : Trajet demain ${ride.departure_city || ride.origin} → ${ride.arrival_city || ride.destination} à ${ride.time_departure || new Date(ride.departure_datetime).toLocaleTimeString('fr-FR', { hour: '2-digit', minute: '2-digit' })}`,
                metadata: {
                  rideId: ride.id,
                  reservationId: booking.id,
                  origin: ride.departure_city || ride.origin,
                  destination: ride.arrival_city || ride.destination,
                  dateDeparture: ride.date_departure || new Date(ride.departure_datetime).toISOString().split('T')[0],
                  timeDeparture: ride.time_departure || new Date(ride.departure_datetime).toLocaleTimeString('fr-FR', { hour: '2-digit', minute: '2-digit' }),
                },
                channels: ['in_app', 'push'],
                phoneNumber: passenger?.phone_number,
              },
            });
          }
        }

        jMinus1Count++;
      }
    }

    // ================================================
    // H-1 REMINDERS (1h before)
    // ================================================

    const { data: ridesHMinus1 } = await supabase
      .from('carpool_rides')
      .select('*, user_profiles!carpool_rides_driver_id_fkey(full_name, phone_number)')
      .gte('departure_datetime', in59Minutes.toISOString())
      .lte('departure_datetime', in1Hour.toISOString())
      .in('ride_status', ['pending', 'started'])
      .not('status', 'eq', 'cancelled');

    if (ridesHMinus1 && ridesHMinus1.length > 0) {
      console.log(`⏰ Found ${ridesHMinus1.length} rides for H-1 reminders`);

      for (const ride of ridesHMinus1) {
        const driver = ride.user_profiles;

        // Notify driver (with WhatsApp)
        await supabase.functions.invoke('send-notification-unified', {
          body: {
            type: 'reminder_h_minus_1',
            userId: ride.driver_id,
            title: '⏰ Trajet dans 1 heure',
            message: 'Ton trajet démarre dans 1h',
            metadata: {
              rideId: ride.id,
              origin: ride.departure_city || ride.origin,
              destination: ride.arrival_city || ride.destination,
              dateDeparture: ride.date_departure || new Date(ride.departure_datetime).toISOString().split('T')[0],
              timeDeparture: ride.time_departure || new Date(ride.departure_datetime).toLocaleTimeString('fr-FR', { hour: '2-digit', minute: '2-digit' }),
            },
            channels: ['in_app', 'push', 'whatsapp'],
            phoneNumber: driver?.phone_number,
          },
        });

        // Get confirmed passengers
        const { data: bookings } = await supabase
          .from('carpool_bookings')
          .select('*, user_profiles!carpool_bookings_passenger_id_fkey(full_name, phone_number)')
          .eq('ride_id', ride.id)
          .eq('status', 'accepted');

        if (bookings && bookings.length > 0) {
          for (const booking of bookings) {
            const passenger = booking.user_profiles;

            await supabase.functions.invoke('send-notification-unified', {
              body: {
                type: 'reminder_h_minus_1',
                userId: booking.passenger_id,
                title: '⏰ Trajet dans 1 heure',
                message: 'Ton trajet démarre dans 1h. Sois à l\'heure 📍',
                metadata: {
                  rideId: ride.id,
                  reservationId: booking.id,
                  origin: ride.departure_city || ride.origin,
                  destination: ride.arrival_city || ride.destination,
                  dateDeparture: ride.date_departure || new Date(ride.departure_datetime).toISOString().split('T')[0],
                  timeDeparture: ride.time_departure || new Date(ride.departure_datetime).toLocaleTimeString('fr-FR', { hour: '2-digit', minute: '2-digit' }),
                },
                channels: ['in_app', 'push', 'whatsapp'],
                phoneNumber: passenger?.phone_number,
              },
            });
          }
        }

        hMinus1Count++;
      }
    }

    console.log(`✅ Reminders sent: J-1=${jMinus1Count}, H-1=${hMinus1Count}`);

    return new Response(
      JSON.stringify({
        success: true,
        jMinus1Reminders: jMinus1Count,
        hMinus1Reminders: hMinus1Count,
      }),
      {
        headers: { ...corsHeaders, 'Content-Type': 'application/json' },
        status: 200,
      }
    );
  } catch (error) {
    console.error('❌ Error in on-ride-reminders:', error);
    return new Response(
      JSON.stringify({ success: false, error: error.message }),
      {
        headers: { ...corsHeaders, 'Content-Type': 'application/json' },
        status: 500,
      }
    );
  }
});

// Edge Function: on-driver-arrived
// Triggered when driver clicks "Je suis arrivé"
// Tasks:
// - Send push + WhatsApp to passengers
// - Create in-app popup

import { serve } from 'https://deno.land/std@0.168.0/http/server.ts';
import { createClient } from 'https://esm.sh/@supabase/supabase-js@2';

const corsHeaders = {
  'Access-Control-Allow-Origin': '*',
  'Access-Control-Allow-Headers': 'authorization, x-client-info, apikey, content-type',
};

interface DriverArrivedPayload {
  rideId: string;
  driverId: string;
  driverName: string;
  meetingPoint: string;
}

serve(async (req) => {
  if (req.method === 'OPTIONS') {
    return new Response('ok', { headers: corsHeaders });
  }

  try {
    const payload: DriverArrivedPayload = await req.json();

    console.log('📥 on-driver-arrived:', payload);

    const supabaseUrl = Deno.env.get('SUPABASE_URL') || '';
    const supabaseKey = Deno.env.get('SUPABASE_SERVICE_ROLE_KEY') || '';
    const supabase = createClient(supabaseUrl, supabaseKey);

    // Get confirmed passengers
    const { data: bookings } = await supabase
      .from('carpool_bookings')
      .select('*, user_profiles!carpool_bookings_passenger_id_fkey(full_name, phone_number)')
      .eq('ride_id', payload.rideId)
      .eq('status', 'accepted');

    if (!bookings || bookings.length === 0) {
      console.log('⚠️ No confirmed passengers found');
      return new Response(
        JSON.stringify({ success: true, passengersNotified: 0 }),
        {
          headers: { ...corsHeaders, 'Content-Type': 'application/json' },
          status: 200,
        }
      );
    }

    // Notify each passenger
    for (const booking of bookings) {
      const passenger = booking.user_profiles;

      await supabase.functions.invoke('send-notification-unified', {
        body: {
          type: 'driver_arrived',
          userId: booking.passenger_id,
          title: '📍 Le conducteur est arrivé !',
          message: `${payload.driverName} est arrivé au point de rencontre. Rejoignez-le dans les 5 minutes.`,
          metadata: {
            rideId: payload.rideId,
            reservationId: booking.id,
            driverName: payload.driverName,
            meetingPoint: payload.meetingPoint,
          },
          channels: ['in_app', 'push', 'whatsapp'],
          phoneNumber: passenger?.phone_number,
        },
      });
    }

    console.log(`✅ Notified ${bookings.length} passengers`);

    return new Response(
      JSON.stringify({
        success: true,
        passengersNotified: bookings.length,
      }),
      {
        headers: { ...corsHeaders, 'Content-Type': 'application/json' },
        status: 200,
      }
    );
  } catch (error) {
    console.error('❌ Error in on-driver-arrived:', error);
    return new Response(
      JSON.stringify({ success: false, error: error.message }),
      {
        headers: { ...corsHeaders, 'Content-Type': 'application/json' },
        status: 500,
      }
    );
  }
});

// Edge Function: on-ride-status-changed
// Triggered when ride status changes
// Tasks:
// - in_progress: in-app for passengers
// - cancelled_by_driver: push + WhatsApp to passengers
// - cancelled_by_passenger: push to driver
// - completed: status updated

import { serve } from 'https://deno.land/std@0.168.0/http/server.ts';
import { createClient } from 'https://esm.sh/@supabase/supabase-js@2';

const corsHeaders = {
  'Access-Control-Allow-Origin': '*',
  'Access-Control-Allow-Headers': 'authorization, x-client-info, apikey, content-type',
};

interface RideStatusChangedPayload {
  rideId: string;
  status: 'pending' | 'started' | 'ended' | 'cancelled';
  driverId: string;
  driverName: string;
  origin: string;
  destination: string;
  dateDeparture: string;
  timeDeparture: string;
  cancelledBy?: 'driver' | 'passenger';
  cancelledPassengerId?: string;
  cancelledPassengerName?: string;
}

serve(async (req) => {
  if (req.method === 'OPTIONS') {
    return new Response('ok', { headers: corsHeaders });
  }

  try {
    const payload: RideStatusChangedPayload = await req.json();

    console.log('📥 on-ride-status-changed:', payload);

    const supabaseUrl = Deno.env.get('SUPABASE_URL') || '';
    const supabaseKey = Deno.env.get('SUPABASE_SERVICE_ROLE_KEY') || '';
    const supabase = createClient(supabaseUrl, supabaseKey);

    if (payload.status === 'started') {
      // Notify passengers that ride has started
      const { data: bookings } = await supabase
        .from('carpool_bookings')
        .select('passenger_id')
        .eq('ride_id', payload.rideId)
        .eq('status', 'accepted');

      if (bookings && bookings.length > 0) {
        for (const booking of bookings) {
          await supabase.functions.invoke('send-notification-unified', {
            body: {
              type: 'ride_started',
              userId: booking.passenger_id,
              title: '🚗 Trajet démarré',
              message: `Le trajet ${payload.origin} → ${payload.destination} a démarré`,
              metadata: {
                rideId: payload.rideId,
                origin: payload.origin,
                destination: payload.destination,
              },
              channels: ['in_app'],
            },
          });
        }
      }
    } else if (payload.status === 'cancelled' && payload.cancelledBy === 'driver') {
      // Notify passengers of cancellation
      const { data: bookings } = await supabase
        .from('carpool_bookings')
        .select('*, user_profiles!carpool_bookings_passenger_id_fkey(phone_number)')
        .eq('ride_id', payload.rideId)
        .eq('status', 'accepted');

      if (bookings && bookings.length > 0) {
        for (const booking of bookings) {
          const passenger = booking.user_profiles;

          await supabase.functions.invoke('send-notification-unified', {
            body: {
              type: 'ride_cancelled',
              userId: booking.passenger_id,
              title: '❌ Trajet annulé',
              message: `${payload.driverName} a annulé ${payload.origin} → ${payload.destination}`,
              metadata: {
                rideId: payload.rideId,
                driverName: payload.driverName,
                origin: payload.origin,
                destination: payload.destination,
                dateDeparture: payload.dateDeparture,
              },
              channels: ['in_app', 'push', 'whatsapp'],
              phoneNumber: passenger?.phone_number,
            },
          });
        }
      }
    } else if (payload.status === 'cancelled' && payload.cancelledBy === 'passenger') {
      // Notify driver of passenger cancellation
      await supabase.functions.invoke('send-notification-unified', {
        body: {
          type: 'reservation_cancelled_by_passenger',
          userId: payload.driverId,
          title: '❌ Annulation de réservation',
          message: `${payload.cancelledPassengerName} a annulé sa réservation`,
          metadata: {
            rideId: payload.rideId,
            passengerId: payload.cancelledPassengerId,
            passengerName: payload.cancelledPassengerName,
          },
          channels: ['in_app', 'push'],
        },
      });
    } else if (payload.status === 'ended') {
      // Ride completed - notifications handled by on-rating-request
      console.log('✅ Ride ended, rating requests will be sent by scheduled job');
    }

    return new Response(
      JSON.stringify({ success: true }),
      {
        headers: { ...corsHeaders, 'Content-Type': 'application/json' },
        status: 200,
      }
    );
  } catch (error) {
    console.error('❌ Error in on-ride-status-changed:', error);
    return new Response(
      JSON.stringify({ success: false, error: error.message }),
      {
        headers: { ...corsHeaders, 'Content-Type': 'application/json' },
        status: 500,
      }
    );
  }
});

// Edge Function: on-rating-request
// Scheduled cron job to request ratings
// Tasks:
// - Find rides ended 10-30 minutes ago
// - Send push notifications to request ratings
// - Create in-app notifications

import { serve } from 'https://deno.land/std@0.168.0/http/server.ts';
import { createClient } from 'https://esm.sh/@supabase/supabase-js@2';

const corsHeaders = {
  'Access-Control-Allow-Origin': '*',
  'Access-Control-Allow-Headers': 'authorization, x-client-info, apikey, content-type',
};

serve(async (req) => {
  if (req.method === 'OPTIONS') {
    return new Response('ok', { headers: corsHeaders });
  }

  try {
    console.log('📥 on-rating-request: Starting scheduled job');

    const supabaseUrl = Deno.env.get('SUPABASE_URL') || '';
    const supabaseKey = Deno.env.get('SUPABASE_SERVICE_ROLE_KEY') || '';
    const supabase = createClient(supabaseUrl, supabaseKey);

    const now = new Date();
    const thirtyMinutesAgo = new Date(now.getTime() - 30 * 60 * 1000);
    const tenMinutesAgo = new Date(now.getTime() - 10 * 60 * 1000);

    // Find rides that ended 10-30 minutes ago and haven't had rating requests sent
    const { data: rides } = await supabase
      .from('carpool_rides')
      .select('*, user_profiles!carpool_rides_driver_id_fkey(full_name, phone_number)')
      .eq('ride_status', 'ended')
      .gte('ended_at', thirtyMinutesAgo.toISOString())
      .lte('ended_at', tenMinutesAgo.toISOString())
      .is('rating_requested_at', null);

    if (!rides || rides.length === 0) {
      console.log('⚠️ No rides found for rating requests');
      return new Response(
        JSON.stringify({ success: true, ridesProcessed: 0 }),
        {
          headers: { ...corsHeaders, 'Content-Type': 'application/json' },
          status: 200,
        }
      );
    }

    console.log(`⭐ Found ${rides.length} rides for rating requests`);

    for (const ride of rides) {
      // Request rating from driver
      await supabase.functions.invoke('send-notification-unified', {
        body: {
          type: 'rating_request',
          userId: ride.driver_id,
          title: '⭐ Note tes passagers',
          message: 'Comment s\'est passé ton trajet ? Note tes passagers',
          metadata: {
            rideId: ride.id,
            origin: ride.departure_city || ride.origin,
            destination: ride.arrival_city || ride.destination,
            isDriver: true,
          },
          channels: ['in_app', 'push'],
        },
      });

      // Get confirmed passengers
      const { data: bookings } = await supabase
        .from('carpool_bookings')
        .select('passenger_id')
        .eq('ride_id', ride.id)
        .eq('status', 'accepted');

      if (bookings && bookings.length > 0) {
        for (const booking of bookings) {
          await supabase.functions.invoke('send-notification-unified', {
            body: {
              type: 'rating_request',
              userId: booking.passenger_id,
              title: '⭐ Note ton conducteur',
              message: `Note ton conducteur pour le trajet ${ride.departure_city || ride.origin} → ${ride.arrival_city || ride.destination} 🚗`,
              metadata: {
                rideId: ride.id,
                reservationId: booking.id,
                origin: ride.departure_city || ride.origin,
                destination: ride.arrival_city || ride.destination,
                isDriver: false,
              },
              channels: ['in_app', 'push'],
            },
          });
        }
      }

      // Mark rating request as sent
      await supabase
        .from('carpool_rides')
        .update({ rating_requested_at: now.toISOString() })
        .eq('id', ride.id);
    }

    console.log(`✅ Rating requests sent for ${rides.length} rides`);

    return new Response(
      JSON.stringify({
        success: true,
        ridesProcessed: rides.length,
      }),
      {
        headers: { ...corsHeaders, 'Content-Type': 'application/json' },
        status: 200,
      }
    );
  } catch (error) {
    console.error('❌ Error in on-rating-request:', error);
    return new Response(
      JSON.stringify({ success: false, error: error.message }),
      {
        headers: { ...corsHeaders, 'Content-Type': 'application/json' },
        status: 500,
      }
    );
  }
});

