-- Enable pg_net extension for HTTP requests from database
CREATE EXTENSION IF NOT EXISTS pg_net;

-- Grant usage to authenticated and service_role
GRANT USAGE ON SCHEMA net TO postgres, anon, authenticated, service_role;

-- Create a table to store Supabase configuration
CREATE TABLE IF NOT EXISTS app_config (
  key text PRIMARY KEY,
  value text NOT NULL,
  updated_at timestamptz DEFAULT now()
);

-- Enable RLS on app_config
ALTER TABLE app_config ENABLE ROW LEVEL SECURITY;

-- Only service_role can read/write config
CREATE POLICY "Service role can manage config" ON app_config
  FOR ALL
  USING (auth.role() = 'service_role')
  WITH CHECK (auth.role() = 'service_role');

-- Insert Supabase URL (will be updated by Edge Function or manually)
INSERT INTO app_config (key, value)
VALUES 
  ('supabase_url', 'https://drxtaxepofuoelplgrei.supabase.co'),
  ('service_role_key', 'YOUR_SERVICE_ROLE_KEY_HERE')
ON CONFLICT (key) DO UPDATE SET value = EXCLUDED.value, updated_at = now();

COMMENT ON TABLE app_config IS 'Application configuration for database triggers and functions';

-- ================================================
-- Update triggers to use pg_net for HTTP requests
-- ================================================

-- ================================================
-- 1. RIDE CREATION TRIGGER (Updated)
-- ================================================

CREATE OR REPLACE FUNCTION trigger_on_ride_created_fn()
RETURNS TRIGGER
LANGUAGE plpgsql
SECURITY DEFINER
AS $$
DECLARE
  supabase_url text;
  service_role_key text;
  payload jsonb;
  request_id bigint;
BEGIN
  -- Get configuration
  SELECT value INTO supabase_url FROM app_config WHERE key = 'supabase_url';
  SELECT value INTO service_role_key FROM app_config WHERE key = 'service_role_key';

  -- Skip if config not set
  IF supabase_url IS NULL OR service_role_key IS NULL OR service_role_key = 'YOUR_SERVICE_ROLE_KEY_HERE' THEN
    RAISE WARNING 'Supabase config not set in app_config table';
    RETURN NEW;
  END IF;

  -- Build payload
  payload := jsonb_build_object(
    'rideId', NEW.id,
    'driverId', NEW.driver_id,
    'origin', COALESCE(NEW.origin, NEW.departure_city),
    'destination', COALESCE(NEW.destination, NEW.arrival_city),
    'dateDeparture', COALESCE(NEW.date_departure::text, NEW.departure_datetime::date::text),
    'timeDeparture', COALESCE(NEW.time_departure::text, NEW.departure_datetime::time::text),
    'price', COALESCE(NEW.price, NEW.price_per_seat),
    'seatsAvailable', NEW.seats_available
  );

  -- Call Edge Function using pg_net
  SELECT INTO request_id net.http_post(
    url := supabase_url || '/functions/v1/on-ride-created',
    headers := jsonb_build_object(
      'Content-Type', 'application/json',
      'Authorization', 'Bearer ' || service_role_key
    ),
    body := payload
  );

  RAISE LOG 'Called on-ride-created Edge Function, request_id: %', request_id;

  RETURN NEW;
EXCEPTION
  WHEN OTHERS THEN
    RAISE WARNING 'Failed to call on-ride-created Edge Function: %', SQLERRM;
    RETURN NEW;
END;
$$;

-- ================================================
-- 2. RESERVATION REQUEST TRIGGER (Updated)
-- ================================================

CREATE OR REPLACE FUNCTION trigger_on_reservation_requested_fn()
RETURNS TRIGGER
LANGUAGE plpgsql
SECURITY DEFINER
AS $$
DECLARE
  supabase_url text;
  service_role_key text;
  payload jsonb;
  ride_data record;
  request_id bigint;
BEGIN
  -- Get configuration
  SELECT value INTO supabase_url FROM app_config WHERE key = 'supabase_url';
  SELECT value INTO service_role_key FROM app_config WHERE key = 'service_role_key';

  -- Skip if config not set
  IF supabase_url IS NULL OR service_role_key IS NULL OR service_role_key = 'YOUR_SERVICE_ROLE_KEY_HERE' THEN
    RAISE WARNING 'Supabase config not set in app_config table';
    RETURN NEW;
  END IF;

  -- Get ride details
  SELECT 
    r.*,
    up.phone_number as driver_phone
  INTO ride_data
  FROM carpool_rides r
  LEFT JOIN user_profiles up ON up.id = r.driver_id
  WHERE r.id = NEW.ride_id;

  -- Build payload
  payload := jsonb_build_object(
    'reservationId', NEW.id,
    'rideId', NEW.ride_id,
    'passengerId', NEW.passenger_id,
    'passengerName', NEW.passenger_name,
    'passengerPhone', NEW.passenger_phone,
    'numberOfPassengers', NEW.number_of_passengers,
    'driverId', ride_data.driver_id,
    'driverPhone', ride_data.driver_phone,
    'origin', COALESCE(ride_data.origin, ride_data.departure_city),
    'destination', COALESCE(ride_data.destination, ride_data.arrival_city),
    'dateDeparture', COALESCE(ride_data.date_departure::text, ride_data.departure_datetime::date::text),
    'timeDeparture', COALESCE(ride_data.time_departure::text, ride_data.departure_datetime::time::text)
  );

  -- Call Edge Function
  SELECT INTO request_id net.http_post(
    url := supabase_url || '/functions/v1/on-reservation-requested',
    headers := jsonb_build_object(
      'Content-Type', 'application/json',
      'Authorization', 'Bearer ' || service_role_key
    ),
    body := payload
  );

  RAISE LOG 'Called on-reservation-requested Edge Function, request_id: %', request_id;

  RETURN NEW;
EXCEPTION
  WHEN OTHERS THEN
    RAISE WARNING 'Failed to call on-reservation-requested Edge Function: %', SQLERRM;
    RETURN NEW;
END;
$$;

-- ================================================
-- 3. RESERVATION STATUS CHANGE TRIGGER (Updated)
-- ================================================

CREATE OR REPLACE FUNCTION trigger_on_reservation_status_changed_fn()
RETURNS TRIGGER
LANGUAGE plpgsql
SECURITY DEFINER
AS $$
DECLARE
  supabase_url text;
  service_role_key text;
  payload jsonb;
  ride_data record;
  passenger_data record;
  request_id bigint;
BEGIN
  -- Only trigger on status change to accepted or refused
  IF NEW.status != OLD.status AND (NEW.status = 'accepted' OR NEW.status = 'refused') THEN

    -- Get configuration
    SELECT value INTO supabase_url FROM app_config WHERE key = 'supabase_url';
    SELECT value INTO service_role_key FROM app_config WHERE key = 'service_role_key';

    -- Skip if config not set
    IF supabase_url IS NULL OR service_role_key IS NULL OR service_role_key = 'YOUR_SERVICE_ROLE_KEY_HERE' THEN
      RAISE WARNING 'Supabase config not set in app_config table';
      RETURN NEW;
