-- 3. Create cron jobs for reminders and rating requests
-- Ride reminders (every 10 minutes)
SELECT cron.schedule(
  'ride-reminders',
  '*/10 * * * *',
  $$
  SELECT net.http_post(
    url := 'https://drxtaxepofuoelplgrei.supabase.co/functions/v1/on-ride-reminders',
    headers := jsonb_build_object(
      'Content-Type', 'application/json'
    ),
    body := '{}'::jsonb
  );
  $$
);

-- Rating requests (every 5 minutes)
SELECT cron.schedule(
  'rating-requests',
  '*/5 * * * *',
  $$
  SELECT net.http_post(
    url := 'https://drxtaxepofuoelplgrei.supabase.co/functions/v1/on-rating-request',
    headers := jsonb_build_object(
      'Content-Type', 'application/json'
    ),
    body := '{}'::jsonb
  );
  $$
);

-- 4. Add index for better performance on notifications
CREATE INDEX IF NOT EXISTS idx_notifications_user_unread 
  ON notifications(user_id, is_read, created_at DESC);

CREATE INDEX IF NOT EXISTS idx_carpool_rides_departure_status 
  ON carpool_rides(departure_datetime, ride_status) 
  WHERE ride_status IN ('pending', 'started');

CREATE INDEX IF NOT EXISTS idx_carpool_rides_ended_rating 
